import { ChevronRight } from 'lucide-react';
import { useCallback, useEffect, useState } from 'react';
import { toast } from 'sonner';
import { CharacterTypeManager } from './components/CharacterTypeManager';
import { DataExportImport } from './components/DataExportImport';
import { GraphicsEffectEditorNew } from './components/GraphicsEffectEditorNew';
import { defaultBindings, KeyBindings, KeyBindingSettings } from './components/KeyBindingSettings';
import { MakeConfigGuide } from './components/MakeConfigGuide';
import { MonsterDatasetViewer } from './components/MonsterDatasetViewer';
import { MonsterTypeDefinition, MonsterTypeStats } from './components/MonsterTypeDefinition';
import { MultiMonsterSimulator } from './components/MultiMonsterSimulator';
import { PlayerDatasetViewer } from './components/PlayerDatasetViewer';
import { SimulatorSettings } from './components/SimulatorSettings';
import { SkillAndItemSettings } from './components/SkillAndItemSettings';
import { SkillWorkspace } from './components/SkillWorkspace';
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
} from './components/ui/sidebar';
import { Toaster } from './components/ui/sonner';
import {
  applyMonsterRowFromData,
  applyPlayerRowFromData,
} from './features/simulator/rowApplyManager';
import { createInitialDatasets, createInitialMonsterTypeStats } from './features/simulator/setup';
import { APP_MENU_ITEMS } from './features/ui/navigation/menuConfig';
import { CharacterTypeInfo, DEFAULT_CHARACTER_TYPES } from './lib/characterTypes';
import { CharacterConfig } from './lib/gameTypes';
import { getDefaultItemSlots, ItemSlot } from './lib/itemSystem';
import { updateDataRowWithLevel } from './lib/levelBasedStats';
import {
  defaultMonsterLevelConfig,
  defaultPlayerLevelConfig,
  LevelConfig,
} from './lib/levelSystem';
import { DataRow, mockDataset } from './lib/mockData';
import { DEFAULT_MAX_MONSTER_COUNT, DEFAULT_RESPAWN_DELAY } from './lib/simulator/constants';
import {
  BasicAttackSlot,
  defaultSkills,
  getDefaultBasicAttackSlot,
  getDefaultSkillSlots,
  Skill,
  SkillSlot,
} from './lib/skillSystem';
import { APP_VIEW, AppView, SETTINGS_VIEW_PREFIX } from './shared/constants/appViews';

export default function App() {
  const initialDatasets = createInitialDatasets();
  const [currentView, setCurrentView] = useState<AppView>(APP_VIEW.SIMULATOR);
  const [currentTick, setCurrentTick] = useState(0);
  const [currentDataRow, setCurrentDataRow] = useState<DataRow | null>(mockDataset[0] || null);
  const [keyBindings, setKeyBindings] = useState<KeyBindings>(defaultBindings);

  // Character types state
  const [characterTypes, setCharacterTypes] =
    useState<CharacterTypeInfo[]>(DEFAULT_CHARACTER_TYPES);

  // Level system state
  const [playerLevelConfig, setPlayerLevelConfig] = useState<LevelConfig>(defaultPlayerLevelConfig);
  const [monsterLevelConfig, setMonsterLevelConfig] =
    useState<LevelConfig>(defaultMonsterLevelConfig);

  // Skill system state
  const [playerBasicAttack, setPlayerBasicAttack] = useState<BasicAttackSlot>(
    getDefaultBasicAttackSlot('melee', DEFAULT_CHARACTER_TYPES[0]?.defaultBasicAttackId)
  );
  const [monsterBasicAttack, setMonsterBasicAttack] = useState<BasicAttackSlot>(
    getDefaultBasicAttackSlot('melee', DEFAULT_CHARACTER_TYPES[0]?.defaultBasicAttackId)
  );
  const [skillSlots, setSkillSlots] = useState<SkillSlot[]>(getDefaultSkillSlots());
  const [skillConfigs, setSkillConfigs] = useState<Record<string, Skill>>(defaultSkills);

  // Item system state
  const [itemSlots, setItemSlots] = useState<ItemSlot[]>(getDefaultItemSlots());

  // Projectile settings
  const [homingProjectiles, setHomingProjectiles] = useState<boolean>(false);

  // Monster spawn settings
  const [maxMonsterCount, setMaxMonsterCount] = useState<number>(DEFAULT_MAX_MONSTER_COUNT);
  const [respawnDelay, setRespawnDelay] = useState<number>(DEFAULT_RESPAWN_DELAY);

  // Monster type definitions (프리셋 기반)
  const [monsterTypeStats, setMonsterTypeStats] = useState<Record<string, MonsterTypeStats>>(
    createInitialMonsterTypeStats()
  );

  // Separate datasets for player and monster
  const [playerDataset, setPlayerDataset] = useState<DataRow[]>(initialDatasets.playerDataset);
  const [monsterDataset, setMonsterDataset] = useState<DataRow[]>(initialDatasets.monsterDataset);

  // Monster row selection for multi-spawn (1:다 시뮬레이터)
  const [selectedMonsterRows, setSelectedMonsterRows] = useState<Set<number>>(new Set());

  const [playerConfig, setPlayerConfig] = useState<CharacterConfig>({
    size: { min: 18, max: 22 },
    speed: { min: 140, max: 160 },
    attack: { min: 45, max: 55 },
    defense: { min: 18, max: 22 },
    attackSpeed: { min: 1.4, max: 1.6 },
    accuracy: { min: 80, max: 90 },
    criticalRate: { min: 20, max: 30 },
    attackRange: { min: 75, max: 85 },
    attackWidth: { min: 85, max: 95 },
    typeId: DEFAULT_CHARACTER_TYPES[0]?.id || 'warrior', // 타입 프리셋 ID (첫 번째 타입)
    attackType: DEFAULT_CHARACTER_TYPES[0]?.id || 'warrior', // 첫 번째 타입
    monsterRespawnDelay: DEFAULT_RESPAWN_DELAY,
    monsterMaxCount: 3,
  });

  const [monsterConfig, setMonsterConfig] = useState<CharacterConfig>({
    size: { min: 22, max: 26 },
    speed: { min: 55, max: 65 },
    attack: { min: 35, max: 45 },
    defense: { min: 13, max: 17 },
    attackSpeed: { min: 0.9, max: 1.1 },
    accuracy: { min: 70, max: 80 },
    criticalRate: { min: 12, max: 18 },
    attackRange: { min: 55, max: 65 },
    attackWidth: { min: 115, max: 125 },
    typeId: DEFAULT_CHARACTER_TYPES[0]?.id || 'warrior', // 타입 프리셋 ID (첫 번째 타입)
    attackType: DEFAULT_CHARACTER_TYPES[0]?.id || 'warrior', // 첫 번째 타입
    monsterRespawnDelay: DEFAULT_RESPAWN_DELAY,
    monsterMaxCount: 3,
  });

  // Update current data row when tick changes (NOT when dataset changes)
  useEffect(() => {
    const playerRow = playerDataset[currentTick];
    const monsterRow = monsterDataset[currentTick];

    // Merge player and monster data for the current tick
    if (playerRow || monsterRow) {
      const mergedRow = {
        ...(playerRow || {}),
        ...(monsterRow || {}),
      } as DataRow;
      setCurrentDataRow(mergedRow);
    }
  }, [currentTick]); // playerDataset, monsterDataset 제거하여 데이터셋 변경 시 재실행 방지

  // 플레이어 레벨 설정(초기값/증가공식) 변경 시 모든 플레이어 데이터 재계산
  useEffect(() => {
    if (playerDataset.length === 0) return;

    const recalculatedDataset = playerDataset.map(row => {
      if (row.player_level === undefined) return row;
      const level = row.player_level || 1;
      const size = row.player_size || 20;
      const typeId = row.player_attack_type;
      const typeInfo = characterTypes.find(t => t.id === typeId);
      return updateDataRowWithLevel(row, true, playerLevelConfig, level, size, typeInfo);
    });

    setPlayerDataset(recalculatedDataset);
    toast.info(`🔄 플레이어 레벨 설정 변경 → ${playerDataset.length}개 행 재계산 완료`);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    playerLevelConfig.baseHp,
    playerLevelConfig.baseSp,
    playerLevelConfig.baseAttack,
    playerLevelConfig.baseDefense,
    playerLevelConfig.baseSpeed,
    playerLevelConfig.hpGrowth.a,
    playerLevelConfig.hpGrowth.b,
    playerLevelConfig.spGrowth.a,
    playerLevelConfig.spGrowth.b,
    playerLevelConfig.attackGrowth.a,
    playerLevelConfig.attackGrowth.b,
    playerLevelConfig.defenseGrowth.a,
    playerLevelConfig.defenseGrowth.b,
    playerLevelConfig.speedGrowth.a,
    playerLevelConfig.speedGrowth.b,
  ]);

  // 몬스터 레벨 설정(초기값/증가공식) 변경 시 모든 몬스터 데이터 재계산
  useEffect(() => {
    if (monsterDataset.length === 0) return;

    const recalculatedDataset = monsterDataset.map(row => {
      if (row.monster_level === undefined) return row;
      const level = row.monster_level || 1;
      const size = row.monster_size || 24;
      const typeId = row.monster_attack_type;
      const typeInfo = characterTypes.find(t => t.id === typeId);
      return updateDataRowWithLevel(row, false, monsterLevelConfig, level, size, typeInfo);
    });

    setMonsterDataset(recalculatedDataset);
    toast.info(`🔄 몬스터 레벨 설정 변경 → ${monsterDataset.length}개 행 재계산 완료`);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    monsterLevelConfig.baseHp,
    monsterLevelConfig.baseSp,
    monsterLevelConfig.baseAttack,
    monsterLevelConfig.baseDefense,
    monsterLevelConfig.baseSpeed,
    monsterLevelConfig.hpGrowth.a,
    monsterLevelConfig.hpGrowth.b,
    monsterLevelConfig.spGrowth.a,
    monsterLevelConfig.spGrowth.b,
    monsterLevelConfig.attackGrowth.a,
    monsterLevelConfig.attackGrowth.b,
    monsterLevelConfig.defenseGrowth.a,
    monsterLevelConfig.defenseGrowth.b,
    monsterLevelConfig.speedGrowth.a,
    monsterLevelConfig.speedGrowth.b,
  ]);

  const handleApplyPlayerRow = useCallback(
    (row: DataRow) => {
      applyPlayerRowFromData({
        row,
        skillConfigs,
        baseSkills: defaultSkills,
        setPlayerLevelConfig,
        setPlayerConfig,
        setPlayerBasicAttack,
        setSkillSlots,
      });
    },
    [skillConfigs]
  );

  const handleApplyMonsterRow = useCallback(
    (row: DataRow) => {
      applyMonsterRowFromData({
        row,
        skillConfigs,
        setMonsterLevelConfig,
        setMonsterConfig,
        setMonsterBasicAttack,
      });
    },
    [skillConfigs]
  );

  // Apply current data row to configs and skills (only when tick changes, NOT when dataset changes)
  useEffect(() => {
    // currentTick이 변경될 때만 실행
    // 데이터셋 내 값 변경 시에는 PlayerDatasetViewer/MonsterDatasetViewer의 onApplyRow로 처리
    const playerRow = playerDataset[currentTick];
    const monsterRow = monsterDataset[currentTick];

    if (playerRow && playerRow.player_size !== undefined) {
      handleApplyPlayerRow(playerRow);
    }
    if (monsterRow && monsterRow.monster_size !== undefined) {
      handleApplyMonsterRow(monsterRow);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentTick]); // playerDataset, monsterDataset 의도적으로 제외하여 데이터셋 변경 시 재실행 방지

  return (
    <>
      <Toaster position='top-right' />
      <SidebarProvider defaultOpen={true}>
        <div className='flex min-h-screen w-full bg-gradient-to-br from-slate-50 to-slate-100'>
          {/* Left Sidebar */}
          <Sidebar>
            <SidebarHeader className='border-b border-sidebar-border p-4'>
              <div className='space-y-1'>
                <h2 className='text-slate-900'>게임 시뮬레이터</h2>
                <p className='text-sm text-slate-600'>스프레드시트 워크플로우</p>
              </div>
            </SidebarHeader>

            <SidebarContent className='overflow-visible'>
              <SidebarGroup>
                <SidebarGroupLabel>메뉴</SidebarGroupLabel>
                <SidebarGroupContent>
                  <SidebarMenu>
                    {APP_MENU_ITEMS.map((item, index) => (
                      <SidebarMenuItem key={item.id || `menu-${index}`}>
                        {item.hasSubmenu ? (
                          // Menu with submenu - hover dropdown
                          <div className='group relative'>
                            <SidebarMenuButton
                              isActive={currentView.startsWith(SETTINGS_VIEW_PREFIX)}
                              tooltip={item.label}
                              className='cursor-default'
                            >
                              <item.icon className='h-4 w-4' />
                              <span>{item.label}</span>
                              <ChevronRight className='ml-auto h-3 w-3 transition-transform group-hover:rotate-90' />
                            </SidebarMenuButton>

                            {/* Submenu - shows on hover */}
                            <div className='absolute left-full top-0 ml-2 hidden w-60 rounded-lg border border-slate-200 bg-white shadow-xl group-hover:block z-[100]'>
                              <div className='p-1.5'>
                                {item.submenu?.map(subItem => (
                                  <button
                                    key={subItem.id}
                                    onClick={() => setCurrentView(subItem.id)}
                                    className={`flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-sm transition-all hover:bg-slate-100 ${
                                      currentView === subItem.id
                                        ? 'bg-blue-50 text-blue-700 font-medium'
                                        : 'text-slate-700'
                                    }`}
                                  >
                                    <span className='flex-1'>{subItem.label}</span>
                                    <subItem.icon className='h-4 w-4 flex-shrink-0' />
                                  </button>
                                ))}
                              </div>
                            </div>
                          </div>
                        ) : (
                          // Regular menu item
                          <SidebarMenuButton
                            onClick={() => item.id && setCurrentView(item.id)}
                            isActive={currentView === item.id}
                            tooltip={item.label}
                          >
                            <item.icon className='h-4 w-4' />
                            <span>{item.label}</span>
                          </SidebarMenuButton>
                        )}
                      </SidebarMenuItem>
                    ))}
                  </SidebarMenu>
                </SidebarGroupContent>
              </SidebarGroup>
            </SidebarContent>

            <SidebarFooter className='border-t border-sidebar-border p-4'>
              <p className='text-xs text-slate-500'>데이터셋 + 시각화 + 동기화</p>
            </SidebarFooter>
          </Sidebar>

          {/* Main Content */}
          <main className='flex-1 overflow-auto'>
            <div className='container max-w-screen-2xl mx-auto p-6 lg:p-8'>
              {/* Simulator View (통합: 1:1 / 1:다) */}
              {currentView === APP_VIEW.SIMULATOR && (
                <div className='space-y-8'>
                  {/* 통합 시뮬레이터 - 모드 전환 가능 */}
                  <MultiMonsterSimulator
                    keyBindings={keyBindings}
                    playerConfig={playerConfig}
                    monsterConfig={monsterConfig}
                    currentTick={currentTick}
                    currentDataRow={currentDataRow}
                    playerLevelConfig={playerLevelConfig}
                    monsterLevelConfig={monsterLevelConfig}
                    skillSlots={skillSlots}
                    skillConfigs={skillConfigs}
                    itemSlots={itemSlots}
                    homingProjectiles={homingProjectiles}
                    maxMonsterCount={maxMonsterCount}
                    respawnDelay={respawnDelay}
                    playerBasicAttack={playerBasicAttack}
                    monsterBasicAttack={monsterBasicAttack}
                    title='시뮬레이터'
                    selectedMonsterRows={selectedMonsterRows}
                    monsterDataset={monsterDataset}
                  />

                  {/* Datasets (Vertical) */}
                  <div className='space-y-6'>
                    <PlayerDatasetViewer
                      dataset={playerDataset}
                      setDataset={setPlayerDataset}
                      currentTick={currentTick}
                      setCurrentTick={setCurrentTick}
                      playerConfig={playerConfig}
                      playerLevelConfig={playerLevelConfig}
                      onApplyRow={handleApplyPlayerRow}
                      characterTypes={characterTypes}
                      skillConfigs={skillConfigs}
                    />
                    <MonsterDatasetViewer
                      dataset={monsterDataset}
                      setDataset={setMonsterDataset}
                      currentTick={currentTick}
                      setCurrentTick={setCurrentTick}
                      monsterConfig={monsterConfig}
                      monsterLevelConfig={monsterLevelConfig}
                      onApplyRow={handleApplyMonsterRow}
                      characterTypes={characterTypes}
                      skillConfigs={skillConfigs}
                      selectedRows={selectedMonsterRows}
                      onSelectedRowsChange={setSelectedMonsterRows}
                      maxMonsterCount={maxMonsterCount}
                      onMaxMonsterCountChange={setMaxMonsterCount}
                      respawnDelay={respawnDelay}
                      onRespawnDelayChange={setRespawnDelay}
                    />
                  </div>
                </div>
              )}

              {/* Key Settings View */}
              {currentView === APP_VIEW.SETTINGS_KEYS && (
                <div className='max-w-4xl mx-auto'>
                  <KeyBindingSettings bindings={keyBindings} onBindingsChange={setKeyBindings} />
                </div>
              )}

              {/* Character Settings View */}
              {currentView === APP_VIEW.SETTINGS_PLAYER && (
                <div className='max-w-5xl mx-auto'>
                  <CharacterTypeManager
                    characterTypes={characterTypes}
                    onCharacterTypesChange={setCharacterTypes}
                  />
                </div>
              )}

              {/* Monster Type Definition View */}
              {currentView === APP_VIEW.SETTINGS_MONSTER && (
                <div className='max-w-4xl mx-auto'>
                  <MonsterTypeDefinition
                    monsterTypeStats={monsterTypeStats}
                    onMonsterTypeStatsChange={setMonsterTypeStats}
                    characterTypes={characterTypes}
                  />
                </div>
              )}

              {/* Level/Experience System View */}
              {currentView === APP_VIEW.SETTINGS_LEVEL && (
                <div className='max-w-6xl mx-auto'>
                  <SimulatorSettings
                    playerLevelConfig={playerLevelConfig}
                    onPlayerLevelConfigChange={setPlayerLevelConfig}
                    monsterLevelConfig={monsterLevelConfig}
                    onMonsterLevelConfigChange={setMonsterLevelConfig}
                    characterTypes={characterTypes}
                    onCharacterTypesChange={setCharacterTypes}
                  />
                </div>
              )}

              {/* Skills & Basic Attack System View */}
              {currentView === APP_VIEW.SETTINGS_SKILLS && (
                <div className='h-[calc(100vh-8rem)] px-6'>
                  <SkillWorkspace
                    skills={skillConfigs}
                    onSkillsChange={setSkillConfigs}
                    playerBasicAttack={playerBasicAttack}
                    monsterBasicAttack={monsterBasicAttack}
                    onPlayerBasicAttackChange={setPlayerBasicAttack}
                    onMonsterBasicAttackChange={setMonsterBasicAttack}
                  />
                </div>
              )}

              {/* Graphics Effect Editor View */}
              {currentView === APP_VIEW.SETTINGS_GRAPHICS && (
                <div className='max-w-5xl mx-auto'>
                  <GraphicsEffectEditorNew
                    showPreview={true}
                    onPresetSelect={preset => {
                      console.log('프리셋 선택됨:', preset);
                      toast.success(`✨ "${preset.name}" 프리셋이 선택되었습니다!`);
                      // 여기에서 선택된 프리셋을 스킬 설정에 적용할 수 있습니다
                    }}
                  />
                </div>
              )}

              {/* Items System View */}
              {currentView === APP_VIEW.SETTINGS_ITEMS && (
                <div className='max-w-4xl mx-auto'>
                  <SkillAndItemSettings
                    skills={skillConfigs}
                    onSkillsChange={setSkillConfigs}
                    itemSlots={itemSlots}
                    onItemSlotsChange={setItemSlots}
                    showOnlyItems={true}
                  />
                </div>
              )}

              {/* Data Export/Import View */}
              {currentView === APP_VIEW.EXPORT && (
                <DataExportImport
                  playerConfig={playerConfig}
                  onPlayerConfigChange={setPlayerConfig}
                  monsterConfig={monsterConfig}
                  onMonsterConfigChange={setMonsterConfig}
                  playerLevelConfig={playerLevelConfig}
                  onPlayerLevelConfigChange={setPlayerLevelConfig}
                  monsterLevelConfig={monsterLevelConfig}
                  onMonsterLevelConfigChange={setMonsterLevelConfig}
                  skillConfigs={skillConfigs}
                  onSkillConfigsChange={setSkillConfigs}
                  playerBasicAttack={playerBasicAttack}
                  onPlayerBasicAttackChange={setPlayerBasicAttack}
                  monsterBasicAttack={monsterBasicAttack}
                  onMonsterBasicAttackChange={setMonsterBasicAttack}
                  itemSlots={itemSlots}
                  onItemSlotsChange={setItemSlots}
                  characterTypes={characterTypes}
                  onCharacterTypesChange={setCharacterTypes}
                  monsterTypeStats={monsterTypeStats}
                  onMonsterTypeStatsChange={setMonsterTypeStats}
                  playerDataset={playerDataset}
                  onPlayerDatasetChange={setPlayerDataset}
                  monsterDataset={monsterDataset}
                  onMonsterDatasetChange={setMonsterDataset}
                />
              )}

              {/* Make View */}
              {currentView === APP_VIEW.MAKE && (
                <div className='max-w-7xl mx-auto'>
                  <MakeConfigGuide />
                </div>
              )}
            </div>
          </main>
        </div>
      </SidebarProvider>
    </>
  );
}

import { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card';
import { Label } from './ui/label';
import { Input } from './ui/input';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select';
import { Plus, Trash2 } from 'lucide-react';
import { CharacterTypeInfo } from '../lib/characterTypes';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from './ui/dialog';

interface CharacterSettingsProps {
  characterTypes: CharacterTypeInfo[];
  onCharacterTypesChange: (types: CharacterTypeInfo[]) => void;
}

const AVAILABLE_COLORS = [
  { id: 'text-red-600', name: '빨강' },
  { id: 'text-blue-600', name: '파랑' },
  { id: 'text-green-600', name: '초록' },
  { id: 'text-yellow-600', name: '노랑' },
  { id: 'text-purple-600', name: '보라' },
  { id: 'text-pink-600', name: '분홍' },
  { id: 'text-orange-600', name: '주황' },
  { id: 'text-teal-600', name: '청록' },
  { id: 'text-indigo-600', name: '남색' },
  { id: 'text-gray-600', name: '회색' },
  { id: 'text-slate-600', name: '슬레이트' },
  { id: 'text-rose-600', name: '장미' },
];

export function CharacterSettings({
  characterTypes,
  onCharacterTypesChange,
}: CharacterSettingsProps) {
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [newType, setNewType] = useState<Partial<CharacterTypeInfo>>({
    id: '',
    name: '',
    description: '',
    color: 'text-gray-600',
  });

  const handleAddType = () => {
    if (!newType.id || !newType.name) {
      toast.error('ID와 이름을 입력해주세요.');
      return;
    }

    // ID 중복 체크
    if (characterTypes.some(t => t.id === newType.id)) {
      toast.error('이미 존재하는 ID입니다.');
      return;
    }

    // ID 유효성 체크 (영문, 숫자, 언더스코어만 허용)
    if (!/^[a-z0-9_]+$/.test(newType.id)) {
      toast.error('ID는 영문 소문자, 숫자, 언더스코어(_)만 사용 가능합니다.');
      return;
    }

    onCharacterTypesChange([
      ...characterTypes,
      {
        id: newType.id!,
        name: newType.name!,
        description: newType.description || '',
        color: newType.color || 'text-gray-600',
      },
    ]);

    setNewType({
      id: '',
      name: '',
      description: '',
      color: 'text-gray-600',
    });
    setIsDialogOpen(false);
    toast.success('새 캐릭터 타입이 추가되었습니다.');
  };

  const handleDeleteType = (id: string) => {
    // 기본 타입(melee, projectile)은 삭제 불가
    if (id === 'melee' || id === 'projectile') {
      toast.error('기본 타입은 삭제할 수 없습니다.');
      return;
    }

    onCharacterTypesChange(characterTypes.filter(t => t.id !== id));
    toast.success('캐릭터 타입이 삭제되었습니다.');
  };

  return (
    <>
      <Card>
        <CardHeader>
          <div className='flex items-center justify-between'>
            <div>
              <CardTitle>캐릭터 타입 관리</CardTitle>
              <CardDescription>게임에서 사용할 캐릭터 타입을 관리합니다</CardDescription>
            </div>
            <Button onClick={() => setIsDialogOpen(true)} size='sm'>
              <Plus className='w-4 h-4 mr-2' />새 타입 추가
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className='space-y-2'>
            {characterTypes.map(type => (
              <div
                key={type.id}
                className='flex items-center justify-between p-3 border rounded-lg hover:bg-gray-50'
              >
                <div className='flex items-center gap-3 flex-1'>
                  <Badge variant='outline' className={type.color}>
                    {type.name}
                  </Badge>
                  <div className='flex flex-col gap-1'>
                    <code className='text-xs text-gray-500'>{type.id}</code>
                    {type.description && (
                      <p className='text-sm text-gray-600'>{type.description}</p>
                    )}
                  </div>
                </div>
                {type.id !== 'melee' && type.id !== 'projectile' && (
                  <Button
                    variant='ghost'
                    size='sm'
                    onClick={() => handleDeleteType(type.id)}
                    className='text-red-600 hover:text-red-700 hover:bg-red-50'
                  >
                    <Trash2 className='w-4 h-4' />
                  </Button>
                )}
                {(type.id === 'melee' || type.id === 'projectile') && (
                  <Badge variant='secondary' className='text-xs'>
                    기본
                  </Badge>
                )}
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Add Type Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>새 캐릭터 타입 추가</DialogTitle>
            <DialogDescription>새로운 캐릭터 타입의 정보를 입력해주세요</DialogDescription>
          </DialogHeader>
          <div className='space-y-4 py-4'>
            <div className='space-y-2'>
              <Label htmlFor='type-id'>ID (영문 소문자, 숫자, _만 가능)</Label>
              <Input
                id='type-id'
                placeholder='예: magic, tank, healer'
                value={newType.id}
                onChange={e => setNewType({ ...newType, id: e.target.value.toLowerCase() })}
              />
            </div>
            <div className='space-y-2'>
              <Label htmlFor='type-name'>이름</Label>
              <Input
                id='type-name'
                placeholder='예: 마법사'
                value={newType.name}
                onChange={e => setNewType({ ...newType, name: e.target.value })}
              />
            </div>
            <div className='space-y-2'>
              <Label htmlFor='type-description'>설명 (선택)</Label>
              <Input
                id='type-description'
                placeholder='예: 강력한 마법 공격'
                value={newType.description}
                onChange={e => setNewType({ ...newType, description: e.target.value })}
              />
            </div>
            <div className='space-y-2'>
              <Label htmlFor='type-color'>색상</Label>
              <Select
                value={newType.color}
                onValueChange={value => setNewType({ ...newType, color: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {AVAILABLE_COLORS.map(color => (
                    <SelectItem key={color.id} value={color.id}>
                      <span className={color.id}>{color.name}</span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant='outline' onClick={() => setIsDialogOpen(false)}>
              취소
            </Button>
            <Button onClick={handleAddType}>추가</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Label } from './ui/label';
import { Badge } from './ui/badge';
import { Separator } from './ui/separator';
import { Tabs, TabsContent, TabsList, TabsTrigger } from './ui/tabs';
import { Plus, Trash2, Users, Calculator, Zap } from 'lucide-react';
import { CharacterTypeInfo } from '../lib/characterTypes';
import { toast } from 'sonner';
import { defaultSkills } from '../lib/skillSystem';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from './ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select';

interface CharacterTypeManagerProps {
  characterTypes: CharacterTypeInfo[];
  onCharacterTypesChange: (types: CharacterTypeInfo[]) => void;
}

const AVAILABLE_COLORS = [
  { id: 'text-red-600', name: '빨강' },
  { id: 'text-blue-600', name: '파랑' },
  { id: 'text-green-600', name: '초록' },
  { id: 'text-yellow-600', name: '노랑' },
  { id: 'text-purple-600', name: '보라' },
  { id: 'text-pink-600', name: '분홍' },
  { id: 'text-orange-600', name: '주황' },
  { id: 'text-teal-600', name: '청록' },
  { id: 'text-indigo-600', name: '남색' },
  { id: 'text-gray-600', name: '회색' },
  { id: 'text-slate-600', name: '슬레이트' },
  { id: 'text-rose-600', name: '장미' },
];

export function CharacterTypeManager({
  characterTypes,
  onCharacterTypesChange,
}: CharacterTypeManagerProps) {
  const [selectedTypeId, setSelectedTypeId] = useState<string | null>(
    characterTypes[0]?.id || null
  );
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [newType, setNewType] = useState<Partial<CharacterTypeInfo>>({
    id: '',
    name: '',
    description: '',
    color: 'text-gray-600',
  });

  const selectedType = characterTypes.find(t => t.id === selectedTypeId);

  // 포뮬러 미리보기 함수
  const evaluateFormulaPreview = (formula: string | undefined, level: number): string => {
    if (!formula || formula.trim() === '') {
      return '-';
    }

    try {
      let expression = formula
        .replace(/level/gi, String(level))
        .replace(/size/gi, String(20))
        .replace(/LEVEL/g, String(level))
        .replace(/SIZE/g, String(20));

      expression = expression
        .replace(/MAX\((.*?),(.*?)\)/gi, (_, a, b) => `Math.max(${a},${b})`)
        .replace(/MIN\((.*?),(.*?)\)/gi, (_, a, b) => `Math.min(${a},${b})`)
        .replace(/ROUND\((.*?)\)/gi, (_, a) => `Math.round(${a})`)
        .replace(/FLOOR\((.*?)\)/gi, (_, a) => `Math.floor(${a})`)
        .replace(/CEIL\((.*?)\)/gi, (_, a) => `Math.ceil(${a})`)
        .replace(/SQRT\((.*?)\)/gi, (_, a) => `Math.sqrt(${a})`)
        .replace(/\^/g, '**');

      const result = Function(`"use strict"; return (${expression})`)();
      return typeof result === 'number' && !isNaN(result)
        ? String(Math.round(result * 10) / 10)
        : '오류';
    } catch (error) {
      return '오류';
    }
  };

  const handleAddType = () => {
    if (!newType.id || !newType.name) {
      toast.error('ID와 이름을 입력해주세요.');
      return;
    }

    // ID 중복 체크
    if (characterTypes.some(t => t.id === newType.id)) {
      toast.error('이미 존재하는 ID입니다.');
      return;
    }

    // ID 유효성 체크 (영문, 숫자, 언더스코어만 허용)
    if (!/^[a-z0-9_]+$/.test(newType.id)) {
      toast.error('ID는 영문 소문자, 숫자, 언더스코어(_)만 사용 가능합니다.');
      return;
    }

    const newCharacterType: CharacterTypeInfo = {
      id: newType.id!,
      name: newType.name!,
      description: newType.description || '',
      color: newType.color || 'text-gray-600',
      defaultLevel: 1,
      defaultSize: 20,
      defaultSkillIds: [],
      statFormulas: {
        hpFormula: '100 + (level - 1) * 20',
        spFormula: '50 + (level - 1) * 10',
        attackFormula: '10 + (level - 1) * 3',
        defenseFormula: '5 + (level - 1) * 2',
        moveSpeedFormula: '100',
        attackSpeedFormula: '1.0',
      },
    };

    onCharacterTypesChange([...characterTypes, newCharacterType]);

    setNewType({
      id: '',
      name: '',
      description: '',
      color: 'text-gray-600',
    });
    setIsDialogOpen(false);
    setSelectedTypeId(newCharacterType.id);
    toast.success('새 캐릭터 타입이 추가되었습니다.');
  };

  const handleDeleteType = (id: string) => {
    // 기본 타입(warrior, archer, mage)은 삭제 불가
    if (id === 'warrior' || id === 'archer' || id === 'mage') {
      toast.error('기본 타입은 삭제할 수 없습니다.');
      return;
    }

    onCharacterTypesChange(characterTypes.filter(t => t.id !== id));

    // 선택된 타입이 삭제되면 첫 번째 타입 선택
    if (selectedTypeId === id) {
      const remainingTypes = characterTypes.filter(t => t.id !== id);
      setSelectedTypeId(remainingTypes[0]?.id || null);
    }

    toast.success('캐릭터 타입이 삭제되었습니다.');
  };

  const handleUpdateType = (updates: Partial<CharacterTypeInfo>) => {
    if (!selectedTypeId) return;

    onCharacterTypesChange(
      characterTypes.map(t => (t.id === selectedTypeId ? { ...t, ...updates } : t))
    );
  };

  const handleFormulaChange = (formulaKey: string, value: string) => {
    if (!selectedType) return;

    handleUpdateType({
      statFormulas: {
        ...selectedType.statFormulas,
        [formulaKey]: value,
      },
    });
  };

  const handleSkillToggle = (skillId: string) => {
    if (!selectedType) return;

    const currentSkills = selectedType.defaultSkillIds || [];
    const newSkills = currentSkills.includes(skillId)
      ? currentSkills.filter(id => id !== skillId)
      : [...currentSkills, skillId];

    handleUpdateType({ defaultSkillIds: newSkills });
  };

  const availableSkills = Object.entries(defaultSkills).map(([id, skill]) => ({
    id,
    name: skill.name,
    description: skill.description || '',
  }));

  return (
    <div className='space-y-6'>
      {/* 타입 목록 카드 */}
      <Card>
        <CardHeader>
          <div className='flex items-center justify-between'>
            <div>
              <CardTitle className='flex items-center gap-2'>
                <Users className='w-5 h-5' />
                캐릭터 타입 관리
              </CardTitle>
              <CardDescription>
                각 캐릭터 타입별로 능력치 계산식과 스킬 세트를 관리합니다
              </CardDescription>
            </div>
            <Button onClick={() => setIsDialogOpen(true)} size='sm'>
              <Plus className='w-4 h-4 mr-2' />새 타입 추가
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className='grid grid-cols-2 md:grid-cols-3 gap-2'>
            {characterTypes.map(type => (
              <div
                key={type.id}
                className={`p-3 border-2 rounded-lg cursor-pointer transition-all ${
                  selectedTypeId === type.id
                    ? 'border-blue-500 bg-blue-50'
                    : 'border-gray-200 hover:border-gray-300'
                }`}
                onClick={() => setSelectedTypeId(type.id)}
              >
                <div className='flex items-center justify-between mb-1'>
                  <Badge variant='outline' className={type.color}>
                    {type.name}
                  </Badge>
                  {type.id !== 'warrior' && type.id !== 'archer' && type.id !== 'mage' && (
                    <Button
                      variant='ghost'
                      size='sm'
                      onClick={e => {
                        e.stopPropagation();
                        handleDeleteType(type.id);
                      }}
                      className='h-6 w-6 p-0'
                    >
                      <Trash2 className='w-3 h-3 text-red-500' />
                    </Button>
                  )}
                </div>
                <code className='text-xs text-gray-500'>{type.id}</code>
                {type.description && (
                  <p className='text-xs text-gray-600 mt-1'>{type.description}</p>
                )}
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* 타입 상세 설정 */}
      {selectedType && (
        <Card>
          <CardHeader>
            <div className='flex items-center gap-3'>
              <Badge variant='outline' className={`${selectedType.color} text-lg px-3 py-1`}>
                {selectedType.name}
              </Badge>
              <div>
                <CardTitle className='text-lg'>{selectedType.description}</CardTitle>
                <CardDescription>
                  <code className='text-xs'>{selectedType.id}</code>
                </CardDescription>
              </div>
            </div>
          </CardHeader>
          <CardContent>
            <Tabs defaultValue='basic'>
              <TabsList className='grid w-full grid-cols-3'>
                <TabsTrigger value='basic' className='flex items-center gap-2'>
                  <Users className='w-4 h-4' />
                  능력치 & 스킬 초기값
                </TabsTrigger>
                <TabsTrigger value='formulas' className='flex items-center gap-2'>
                  <Calculator className='w-4 h-4' />
                  능력치 포뮬러 (고급)
                </TabsTrigger>
                <TabsTrigger value='skills' className='flex items-center gap-2'>
                  <Zap className='w-4 h-4' />
                  스킬 세트 선택
                </TabsTrigger>
              </TabsList>

              {/* 능력치 포뮬러 탭 (고급) */}
              <TabsContent value='formulas' className='space-y-4'>
                <div className='bg-blue-50 border border-blue-200 rounded-lg p-3 mb-4'>
                  <p className='text-sm text-blue-800'>
                    💡 <strong>고급 사용자 전용</strong> - 능력치 계산 포뮬러를 직접 수정합니다.
                    <br />• <strong>사용 가능한 변수:</strong> level (캐릭터 레벨), size (크기)
                    <br />• <strong>사용 가능한 함수:</strong> MAX, MIN, ROUND, FLOOR, CEIL, SQRT
                    <br />
                    예: <code>100 + level * 10</code> → 레벨 1: 110, 레벨 5: 150
                    <br />
                    예: <code>MAX(50, level * 2)</code> → 최소 50 보장
                    <br />
                    <strong>⚠️ "레벨링 시스템 설정" 메뉴에서 더 직관적으로 수정 가능합니다.</strong>
                  </p>
                </div>

                <div className='space-y-4'>
                  <div className='space-y-2'>
                    <div className='flex items-center justify-between'>
                      <Label htmlFor='hpFormula'>HP 포뮬러</Label>
                      {selectedType.statFormulas?.hpFormula && (
                        <span className='text-xs text-muted-foreground'>
                          레벨 1: {evaluateFormulaPreview(selectedType.statFormulas.hpFormula, 1)} |
                          레벨 10: {evaluateFormulaPreview(selectedType.statFormulas.hpFormula, 10)}
                        </span>
                      )}
                    </div>
                    <Input
                      id='hpFormula'
                      value={selectedType.statFormulas?.hpFormula || ''}
                      onChange={e => handleFormulaChange('hpFormula', e.target.value)}
                      placeholder='예: 100 + level * 20'
                    />
                  </div>

                  <div className='space-y-2'>
                    <div className='flex items-center justify-between'>
                      <Label htmlFor='spFormula'>SP 포뮬러</Label>
                      {selectedType.statFormulas?.spFormula && (
                        <span className='text-xs text-muted-foreground'>
                          레벨 1: {evaluateFormulaPreview(selectedType.statFormulas.spFormula, 1)} |
                          레벨 10: {evaluateFormulaPreview(selectedType.statFormulas.spFormula, 10)}
                        </span>
                      )}
                    </div>
                    <Input
                      id='spFormula'
                      value={selectedType.statFormulas?.spFormula || ''}
                      onChange={e => handleFormulaChange('spFormula', e.target.value)}
                      placeholder='예: 50 + level * 10'
                    />
                  </div>

                  <div className='space-y-2'>
                    <div className='flex items-center justify-between'>
                      <Label htmlFor='attackFormula'>공격력 포뮬러</Label>
                      {selectedType.statFormulas?.attackFormula && (
                        <span className='text-xs text-muted-foreground'>
                          레벨 1:{' '}
                          {evaluateFormulaPreview(selectedType.statFormulas.attackFormula, 1)} |
                          레벨 10:{' '}
                          {evaluateFormulaPreview(selectedType.statFormulas.attackFormula, 10)}
                        </span>
                      )}
                    </div>
                    <Input
                      id='attackFormula'
                      value={selectedType.statFormulas?.attackFormula || ''}
                      onChange={e => handleFormulaChange('attackFormula', e.target.value)}
                      placeholder='예: 10 + level * 3'
                    />
                  </div>

                  <div className='space-y-2'>
                    <div className='flex items-center justify-between'>
                      <Label htmlFor='defenseFormula'>방어력 포뮬러</Label>
                      {selectedType.statFormulas?.defenseFormula && (
                        <span className='text-xs text-muted-foreground'>
                          레벨 1:{' '}
                          {evaluateFormulaPreview(selectedType.statFormulas.defenseFormula, 1)} |
                          레벨 10:{' '}
                          {evaluateFormulaPreview(selectedType.statFormulas.defenseFormula, 10)}
                        </span>
                      )}
                    </div>
                    <Input
                      id='defenseFormula'
                      value={selectedType.statFormulas?.defenseFormula || ''}
                      onChange={e => handleFormulaChange('defenseFormula', e.target.value)}
                      placeholder='예: 5 + level * 2'
                    />
                  </div>

                  <div className='space-y-2'>
                    <div className='flex items-center justify-between'>
                      <Label htmlFor='moveSpeedFormula'>이동속도 포뮬러</Label>
                      {selectedType.statFormulas?.moveSpeedFormula && (
                        <span className='text-xs text-muted-foreground'>
                          레벨 1:{' '}
                          {evaluateFormulaPreview(selectedType.statFormulas.moveSpeedFormula, 1)} |
                          레벨 10:{' '}
                          {evaluateFormulaPreview(selectedType.statFormulas.moveSpeedFormula, 10)}
                        </span>
                      )}
                    </div>
                    <Input
                      id='moveSpeedFormula'
                      value={selectedType.statFormulas?.moveSpeedFormula || ''}
                      onChange={e => handleFormulaChange('moveSpeedFormula', e.target.value)}
                      placeholder='예: 80 (고정값) 또는 80 + level'
                    />
                  </div>

                  <div className='space-y-2'>
                    <div className='flex items-center justify-between'>
                      <Label htmlFor='attackSpeedFormula'>공격속도 포뮬러</Label>
                      {selectedType.statFormulas?.attackSpeedFormula && (
                        <span className='text-xs text-muted-foreground'>
                          레벨 1:{' '}
                          {evaluateFormulaPreview(selectedType.statFormulas.attackSpeedFormula, 1)}{' '}
                          | 레벨 10:{' '}
                          {evaluateFormulaPreview(selectedType.statFormulas.attackSpeedFormula, 10)}
                        </span>
                      )}
                    </div>
                    <Input
                      id='attackSpeedFormula'
                      value={selectedType.statFormulas?.attackSpeedFormula || ''}
                      onChange={e => handleFormulaChange('attackSpeedFormula', e.target.value)}
                      placeholder='예: 1.0 (고정값) 또는 1.0 + level * 0.05'
                    />
                  </div>

                  <div className='space-y-2'>
                    <div className='flex items-center justify-between'>
                      <Label htmlFor='accuracyFormula'>명중률 포뮬러 (%)</Label>
                      {selectedType.statFormulas?.accuracyFormula && (
                        <span className='text-xs text-muted-foreground'>
                          레벨 1:{' '}
                          {evaluateFormulaPreview(selectedType.statFormulas.accuracyFormula, 1)} |
                          레벨 10:{' '}
                          {evaluateFormulaPreview(selectedType.statFormulas.accuracyFormula, 10)}
                        </span>
                      )}
                    </div>
                    <Input
                      id='accuracyFormula'
                      value={selectedType.statFormulas?.accuracyFormula || ''}
                      onChange={e => handleFormulaChange('accuracyFormula', e.target.value)}
                      placeholder='예: 85 (고정값) 또는 80 + level * 0.5'
                    />
                  </div>

                  <div className='space-y-2'>
                    <div className='flex items-center justify-between'>
                      <Label htmlFor='criticalRateFormula'>크리티컬 확률 포뮬러 (%)</Label>
                      {selectedType.statFormulas?.criticalRateFormula && (
                        <span className='text-xs text-muted-foreground'>
                          레벨 1:{' '}
                          {evaluateFormulaPreview(selectedType.statFormulas.criticalRateFormula, 1)}{' '}
                          | 레벨 10:{' '}
                          {evaluateFormulaPreview(
                            selectedType.statFormulas.criticalRateFormula,
                            10
                          )}
                        </span>
                      )}
                    </div>
                    <Input
                      id='criticalRateFormula'
                      value={selectedType.statFormulas?.criticalRateFormula || ''}
                      onChange={e => handleFormulaChange('criticalRateFormula', e.target.value)}
                      placeholder='예: 15 (고정값) 또는 10 + level * 0.5'
                    />
                  </div>
                </div>
              </TabsContent>

              {/* 스킬 세트 선택 탭 */}
              <TabsContent value='skills' className='space-y-4'>
                <div className='bg-orange-50 border border-orange-200 rounded-lg p-3 mb-4'>
                  <p className='text-sm text-orange-800'>
                    💡 이 캐릭터 타입이 기본적으로 보유할 <strong>기본 공격</strong>과{' '}
                    <strong>스킬 세트</strong>를 설정합니다.
                    <br />
                    • 기본 공격: 플레이어는 마우스 클릭, 몬스터는 AI로 사용합니다.
                    <br />• 스킬 세트: 최대 4개까지 설정 가능하며, 순서대로 슬롯 1~4에 배치됩니다.
                  </p>
                </div>

                {/* 기본 공격 슬롯 */}
                <div className='space-y-2'>
                  <Label>기본 공격 (마우스 클릭)</Label>
                  <Select
                    value={selectedType.defaultBasicAttackId || 'meleeBasic'}
                    onValueChange={value => handleUpdateType({ defaultBasicAttackId: value })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent className='max-h-64'>
                      {availableSkills
                        .filter(skill => {
