                    value={[cooldown / 100]}
                    onValueChange={v => {
                      const newDataset = [...dataset];
                      newDataset[rowIndex] = {
                        ...newDataset[rowIndex],
                        player_basic_attack_cooldown: v[0] * 100,
                      };
                      setDataset(newDataset);
                      // 현재 틱이 변경된 행이면 즉시 반영
                      if (rowIndex === currentTick && onApplyRow) {
                        onApplyRow(newDataset[rowIndex]);
                      }
