                      const newDataset = [...dataset];
                      newDataset[rowIndex] = {
                        ...newDataset[rowIndex],
                        [`player_skill_${slotNum}_width`]: v[0],
                      };
                      setDataset(newDataset);
                    }}
                    min={30}
                    max={360}
                    step={15}
                    className='w-full'
                  />
                </div>

                {/* 데미지 */}
                <div className='space-y-1'>
                  <div className='flex justify-between text-xs'>
                    <Label>데미지</Label>
                    <Badge variant='secondary' className='h-5'>
                      {damage}x
                    </Badge>
                  </div>
                  <Slider
                    value={[damage]}
                    onValueChange={v => {
                      const newDataset = [...dataset];
                      newDataset[rowIndex] = {
                        ...newDataset[rowIndex],
                        [`player_skill_${slotNum}_damage`]: v[0],
                      };
                      setDataset(newDataset);
                    }}
                    min={0.5}
                    max={5.0}
                    step={0.1}
                    className='w-full'
                  />
                </div>

                {/* 쿨타임 */}
                <div className='space-y-1'>
                  <div className='flex justify-between text-xs'>
                    <Label>쿨타임</Label>
                    <Badge variant='secondary' className='h-5'>
                      {cooldown}ms
                    </Badge>
                  </div>
                  <Slider
                    value={[cooldown]}
