              e.stopPropagation();
            }}
            title={`${displayValue}${displayValue !== '-' ? suffix : ''}`}
          >
            {displayValue}
            {displayValue !== '-' ? suffix : ''}
          </div>
        </PopoverTrigger>
        <PopoverContent
          className='w-56 p-4 bg-blue-50 border-blue-400 z-50'
          align='start'
          side='bottom'
          sideOffset={5}
          onClick={e => e.stopPropagation()}
