  } catch (error) {
    console.warn(
      '⚠️ AI 패턴 로드 실패, 기본값 사용:',
      error,
      row.monster_name || 'Unknown Monster'
    );
  }

  // 기본값 반환
  return { ...defaultAIPatternConfig };
}

/**
 * 스킬 쿨타임 업데이트
 */
export function updateSkillCooldowns(skills: CharacterSkills, deltaTime: number): CharacterSkills {
  const deltaMills = deltaTime * 1000;

  const updateSlot = (slot: CharacterSkillSlot | null): CharacterSkillSlot | null => {
    if (!slot) return null;
    return {
      ...slot,
      currentCooldown: Math.max(0, slot.currentCooldown - deltaMills),
    };
  };

  return {
    slot1: updateSlot(skills.slot1),
    slot2: updateSlot(skills.slot2),
    slot3: updateSlot(skills.slot3),
    slot4: updateSlot(skills.slot4),
  };
}

/**
 * 스킬 사용 가능 여부 체크
 */
export function canUseSkill(slot: CharacterSkillSlot | null, currentSP: number): boolean {
  if (!slot || !slot.id) return false;
  if (slot.currentCooldown > 0) return false;
  if (currentSP < slot.spCost) return false;
  return true;
}

/**
 * 사용 가능한 스킬 슬롯 번호 가져오기
 */
export function getAvailableSkills(skills: CharacterSkills, currentSP: number): number[] {
  const available: number[] = [];

  if (canUseSkill(skills.slot1, currentSP)) available.push(1);
  if (canUseSkill(skills.slot2, currentSP)) available.push(2);
  if (canUseSkill(skills.slot3, currentSP)) available.push(3);
  if (canUseSkill(skills.slot4, currentSP)) available.push(4);

  return available;
}

/**
 * 스킬 슬롯 가져오기
 */
export function getSkillSlot(skills: CharacterSkills, slotNum: number): CharacterSkillSlot | null {
  switch (slotNum) {
    case 1:
      return skills.slot1;
    case 2:
      return skills.slot2;
    case 3:
      return skills.slot3;
    case 4:
      return skills.slot4;
    default:
      return null;
  }
}

/**
 * 스킬 사용 (쿨타임 시작)
 */
export function useSkill(skills: CharacterSkills, slotNum: number): CharacterSkills {
  const slot = getSkillSlot(skills, slotNum);
  if (!slot) return skills;

  const updatedSlot = {
    ...slot,
    currentCooldown: slot.cooldown,
  };

  switch (slotNum) {
    case 1:
      return { ...skills, slot1: updatedSlot };
    case 2:
      return { ...skills, slot2: updatedSlot };
    case 3:
      return { ...skills, slot3: updatedSlot };
    case 4:
      return { ...skills, slot4: updatedSlot };
    default:
      return skills;
  }
}

/**
 * 몬스터 AI가 사용할 스킬 결정
 */
export function decideMonsterSkill(
  monster: Monster & { skills: CharacterSkills; aiConfig: AIConfig },
  playerPosition: { x: number; y: number },
  currentHP: number,
  maxHP: number,
  currentSP: number,
  maxSP: number
): number {
  const distance = Math.sqrt(
    Math.pow(playerPosition.x - monster.position.x, 2) +
      Math.pow(playerPosition.y - monster.position.y, 2)
  );

  const availableSkills = getAvailableSkills(monster.skills, currentSP);

  // 스킬 데이터 배열 생성
  const skillData = [
    monster.skills.slot1,
    monster.skills.slot2,
    monster.skills.slot3,
    monster.skills.slot4,
  ].map(slot =>
    slot
      ? {
          id: slot.id,
          range: slot.range,
          width: slot.width,
          damage: slot.damage,
        }
      : null
  );

  return decideSkillToUse(
    monster.aiConfig,
    availableSkills,
    distance,
    currentHP,
    maxHP,
    currentSP,
    maxSP,
    skillData
  );
}

/**
 * 스킬 효과 적용 (힐, 버프 등)
 */
export function applySkillEffect(
  skillId: string,
  character: Character
): { hp?: number; sp?: number; buffApplied?: boolean } {
  const skill = defaultSkills[skillId];
  if (!skill) return {};

  const result: { hp?: number; sp?: number; buffApplied?: boolean } = {};

  // 힐 효과
  if (skill.type === 'heal' && skill.healAmount > 0) {
    result.hp = skill.healAmount;
  }

  // 버프 효과
  if (skill.type === 'buff' && skill.buffDuration > 0) {
    result.buffApplied = true;
    // 버프는 별도 시스템에서 관리 (TODO)
  }

  return result;
}

/**
 * 공격 범위 내 체크 (부채꼴 또는 원형)
 */
export function isInAttackRange(
  attackerPos: { x: number; y: number },
  attackerAngle: number,
  targetPos: { x: number; y: number },
  range: number,
  width: number // 각도 (도 단위)
): boolean {
  const dx = targetPos.x - attackerPos.x;
  const dy = targetPos.y - attackerPos.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  // 거리 체크
  if (distance > range) return false;

  // 전방위 공격 (360도)
  if (width >= 360) return true;

  // 부채꼴 범위 체크
  const angleToTarget = Math.atan2(dy, dx);
  const angleDiff = Math.abs(angleToTarget - attackerAngle);
  const normalizedDiff = Math.min(angleDiff, 2 * Math.PI - angleDiff);
  const halfWidthRad = (width / 2) * (Math.PI / 180);

  return normalizedDiff <= halfWidthRad;
}

/**
 * 크리티컬 판정 결과
 */
export interface CriticalResult {
  isCritical: boolean;
  damageMultiplier: number; // 최종 데미지 배율 (1.0 = 일반, 1.5-2.0 = 크리티컬)
}

/**
 * 크리티컬 판정
 * @param baseCriticalRate 기본 크리티컬 확률 (0.0 ~ 1.0, 기본값 0.15 = 15%)
 * @param criticalMultiplier 크리티컬 데미지 배율 (기본값 1.5 = 150%)
 */
export function calculateCritical(
  baseCriticalRate: number = 0.15,
  criticalMultiplier: number = 1.5
): CriticalResult {
  const isCritical = Math.random() < baseCriticalRate;

  return {
    isCritical,
    damageMultiplier: isCritical ? criticalMultiplier : 1.0,
  };
}

/**
 * 엑셀 스타일 수식을 블록으로 변환하는 고급 파서
 */

import { FormulaBlock, generateBlockId } from './formulaTypes';

// 토큰 타입
type TokenType = 'NUMBER' | 'VARIABLE' | 'FUNCTION' | 'OPERATOR' | 'LPAREN' | 'RPAREN' | 'COMMA';

interface Token {
  type: TokenType;
  value: string;
  position: number;
}

/**
 * 수식을 토큰으로 분해
 */
function tokenize(formula: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < formula.length) {
    const char = formula[i];

    // 공백 무시
    if (/\s/.test(char)) {
      i++;
      continue;
    }

    // 숫자 (소수 포함)
    if (/\d/.test(char) || (char === '.' && i + 1 < formula.length && /\d/.test(formula[i + 1]))) {
      let num = '';
      while (i < formula.length && (/\d/.test(formula[i]) || formula[i] === '.')) {
        num += formula[i];
        i++;
      }
      tokens.push({ type: 'NUMBER', value: num, position: i - num.length });
      continue;
    }

    // 변수 또는 함수 (대문자로 시작)
    if (/[A-Z]/.test(char)) {
      let word = '';
      while (i < formula.length && /[A-Z_]/.test(formula[i])) {
        word += formula[i];
        i++;
      }

      // 다음 문자가 ( 이면 함수
      if (i < formula.length && formula[i] === '(') {
        tokens.push({ type: 'FUNCTION', value: word, position: i - word.length });
      } else {
        tokens.push({ type: 'VARIABLE', value: word, position: i - word.length });
      }
      continue;
    }

    // 연산자
    if ('+-*/^'.includes(char)) {
      tokens.push({ type: 'OPERATOR', value: char, position: i });
      i++;
      continue;
    }

    // 괄호
    if (char === '(') {
      tokens.push({ type: 'LPAREN', value: char, position: i });
      i++;
      continue;
    }

    if (char === ')') {
      tokens.push({ type: 'RPAREN', value: char, position: i });
      i++;
      continue;
    }

    // 쉼표
    if (char === ',') {
      tokens.push({ type: 'COMMA', value: char, position: i });
      i++;
      continue;
    }

    // 알 수 없는 문자
    throw new Error(`알 수 없는 문자: ${char} at position ${i}`);
  }

  return tokens;
}

/**
 * 재귀적 하향 파서
 */
class Parser {
  private tokens: Token[];
  private current: number;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
    this.current = 0;
  }

  private peek(): Token | null {
    return this.current < this.tokens.length ? this.tokens[this.current] : null;
  }

  private consume(): Token {
    return this.tokens[this.current++];
  }

  private expect(type: TokenType): Token {
    const token = this.peek();
    if (!token || token.type !== type) {
      throw new Error(`Expected ${type} but got ${token?.type || 'EOF'}`);
    }
    return this.consume();
  }

  // 수식 파싱 (최상위)
  parse(): FormulaBlock {
    const result = this.parseExpression();
    if (this.current < this.tokens.length) {
      throw new Error('Unexpected tokens after expression');
    }
    return result;
  }

  // 표현식 파싱 (덧셈/뺄셈 우선순위)
  private parseExpression(): FormulaBlock {
    let left = this.parseTerm();

    while (
      this.peek()?.type === 'OPERATOR' &&
      (this.peek()!.value === '+' || this.peek()!.value === '-')
    ) {
      const operator = this.consume().value as '+' | '-';
      const right = this.parseTerm();

      left = {
        id: generateBlockId(),
        type: 'operator',
        operator,
        color: '#f59e0b',
        children: [left, right],
      };
    }

    return left;
  }

  // 항 파싱 (곱셈/나눗셈 우선순위)
  private parseTerm(): FormulaBlock {
    let left = this.parseFactor();

    while (
      this.peek()?.type === 'OPERATOR' &&
      (this.peek()!.value === '*' || this.peek()!.value === '/')
    ) {
      const operator = this.consume().value as '*' | '/';
      const right = this.parseFactor();

      left = {
        id: generateBlockId(),
        type: 'operator',
        operator,
        color: '#f59e0b',
        children: [left, right],
      };
    }

    return left;
  }

  // 인자 파싱 (거듭제곱, 괄호, 변수, 함수, 숫자)
  private parseFactor(): FormulaBlock {
    const base = this.parsePrimary();

    // 거듭제곱 (우결합)
    if (this.peek()?.type === 'OPERATOR' && this.peek()!.value === '^') {
      this.consume();
      const exponent = this.parseFactor(); // 재귀적 호출

      return {
        id: generateBlockId(),
        type: 'operator',
        operator: '^',
        color: '#f59e0b',
        children: [base, exponent],
      };
    }

    return base;
  }

  // 기본 요소 파싱
  private parsePrimary(): FormulaBlock {
    const token = this.peek();

    if (!token) {
      throw new Error('Unexpected end of expression');
    }

    // 숫자
    if (token.type === 'NUMBER') {
      this.consume();
      return {
        id: generateBlockId(),
        type: 'constant',
        value: parseFloat(token.value),
        color: '#10b981',
      };
    }

    // 변수
    if (token.type === 'VARIABLE') {
      this.consume();
      return {
        id: generateBlockId(),
        type: 'variable',
        value: token.value,
        color: '#3b82f6',
      };
    }

    // 함수
    if (token.type === 'FUNCTION') {
      return this.parseFunction();
    }

    // 괄호로 묶인 표현식
    if (token.type === 'LPAREN') {
      this.consume();
      const expr = this.parseExpression();
      this.expect('RPAREN');
      return expr;
    }

    throw new Error(`Unexpected token: ${token.type} "${token.value}"`);
  }

  // 함수 파싱
  private parseFunction(): FormulaBlock {
    const funcToken = this.expect('FUNCTION');
    const funcName = funcToken.value as any;

    this.expect('LPAREN');

    // 파라미터 파싱
    const params: FormulaBlock[] = [];

    if (this.peek()?.type !== 'RPAREN') {
      params.push(this.parseExpression());

      while (this.peek()?.type === 'COMMA') {
        this.consume();
        params.push(this.parseExpression());
      }
    }

    this.expect('RPAREN');

    return {
      id: generateBlockId(),
      type: 'function',
      functionName: funcName,
      color: '#ec4899',
      children: params,
    };
  }
}

/**
 * 엑셀 스타일 수식을 블록으로 변환
 */
export function parseFormulaToBlocks(formula: string): FormulaBlock[] {
  try {
    const tokens = tokenize(formula);
    const parser = new Parser(tokens);
    const block = parser.parse();
    return [block];
  } catch (error) {
    console.error('수식 파싱 오류:', error);
    throw error;
  }
}

/**
 * 수식 유효성 검증
 */
export function validateFormula(formula: string): { valid: boolean; error?: string } {
  try {
    parseFormulaToBlocks(formula);
    return { valid: true };
  } catch (error) {
    return {
      valid: false,
      error: error instanceof Error ? error.message : '알 수 없는 오류',
    };
  }
}

