/**
 * 스킬 조건 인터페이스
 */
export interface SkillCondition {
  type: 'hp_below' | 'hp_above' | 'distance_below' | 'distance_above' | 'sp_above' | 'always';
  value: number; // HP/거리는 절대값, SP는 퍼센트
}

/**
 * 스킬 사용 가능 여부 체크 (조건 확인)
 */
export function checkSkillCondition(
  condition: SkillCondition | undefined,
  monsterHP: number,
  monsterMaxHP: number,
  monsterSP: number,
  monsterMaxSP: number,
  playerDistance: number
): boolean {
  if (!condition || condition.type === 'always') return true;

  const hpPercent = (monsterHP / monsterMaxHP) * 100;
  const spPercent = (monsterSP / monsterMaxSP) * 100;

  switch (condition.type) {
    case 'hp_below':
      return hpPercent < condition.value;
    case 'hp_above':
      return hpPercent > condition.value;
    case 'distance_below':
      return playerDistance < condition.value;
    case 'distance_above':
      return playerDistance > condition.value;
    case 'sp_above':
      return spPercent > condition.value;
    default:
      return true;
  }
}

/**
 * 패턴 조건 체크
 */
export function checkPatternConditions(
  conditions: PatternCondition[],
  distance: number,
  hpPercent: number
): boolean {
  // 조건이 없으면 항상 true
  if (conditions.length === 0) return true;

  // 모든 조건을 만족해야 함 (AND 조건)
  return conditions.every(condition => {
    const value = condition.type === 'distance' ? distance : hpPercent;

    switch (condition.operator) {
      case '<':
        return value < condition.value;
      case '>':
        return value > condition.value;
      case '<=':
        return value <= condition.value;
      case '>=':
        return value >= condition.value;
      default:
        return false;
    }
  });
}

/**
 * 패턴 기반 AI 결정 (새 시스템)
 * @returns { action: PatternAction, skillSlot?: number, skillId?: string } 또는 null
 */
export function evaluateAIPatterns(
  config: AIPatternConfig,
  distance: number,
  monsterHP: number,
  monsterMaxHP: number
): { action: PatternAction; skillSlot?: number; skillId?: string } | null {
  const hpPercent = (monsterHP / monsterMaxHP) * 100;

  // 우선순위 순으로 패턴 체크 (활성화된 패턴만)
  for (const pattern of config.patterns) {
    if (!pattern.enabled) continue;

    // 조건 체크
    if (checkPatternConditions(pattern.conditions, distance, hpPercent)) {
      // 스킬 액션이면 스킬 ID 반환
      if (pattern.action === 'skill') {
        return {
          action: pattern.action,
          skillId: pattern.skillId, // 스킬 ID 포함
        };
      }

      // attack 액션이면 기본 공격 또는 지정된 스킬 ID 반환
      if (pattern.action === 'attack') {
        return {
          action: pattern.action,
          skillId: pattern.skillId, // 기본 공격 스킬 ID 포함
        };
      }

      return { action: pattern.action };
    }
  }

  return null; // 매칭되는 패턴 없음
}

/**
 * 스킬 사용 결정 (AI 우선순위에 따라)
 * @returns 사용할 스킬 슬롯 번호 (1-4) 또는 0 (기본 공격)
 */
export function decideSkillToUse(
  aiConfig: AIConfig,
  availableSkills: number[], // 사용 가능한 스킬 슬롯들 (쿨다운/SP 체크 완료)
  playerDistance: number,
  monsterHP: number,
  monsterMaxHP: number,
  monsterSP: number,
  monsterMaxSP: number,
  skillData: any[] // 각 스킬의 데이터 배열
): number {
  if (availableSkills.length === 0) {
    return 0; // 기본 공격
  }

  const hpPercent = monsterHP / monsterMaxHP;

  // 조건을 만족하는 스킬만 필터링
  const validSkills = availableSkills.filter(slot => {
    const skill = skillData[slot - 1];
    if (!skill || !skill.id) return false; // 스킬이 없으면 제외

    // 거리 체크
    if (skill.range > 0 && playerDistance > skill.range) return false;

    // 조건 체크
    return checkSkillCondition(
      skill.condition,
      monsterHP,
      monsterMaxHP,
      monsterSP,
      monsterMaxSP,
      playerDistance
    );
  });

  if (validSkills.length === 0) {
    return 0; // 조건을 만족하는 스킬이 없으면 기본 공격
  }

  // 스킬 우선순위에 따른 결정
  switch (aiConfig.skillPriority) {
    case 'damage': {
      // 가장 높은 데미지의 스킬 선택
      let maxDamage = 0;
      let bestSkill = 0;
      validSkills.forEach(slot => {
        const skill = skillData[slot - 1];
        if (skill && skill.damage > maxDamage) {
          maxDamage = skill.damage;
          bestSkill = slot;
        }
      });
      return bestSkill || validSkills[0];
    }

    case 'control': {
      // 가장 넓은 범위의 스킬 선택
      let maxWidth = 0;
      let bestControlSkill = 0;
      validSkills.forEach(slot => {
        const skill = skillData[slot - 1];
        if (skill && skill.width > maxWidth) {
          maxWidth = skill.width;
          bestControlSkill = slot;
        }
      });
      return bestControlSkill || validSkills[0];
    }

    case 'survival':
      // HP가 낮으면 힐/버프 스킬 우선
      if (hpPercent < 0.5) {
        const healSkill = validSkills.find(slot => {
          const skill = skillData[slot - 1];
          return skill && (skill.id === 'heal' || skill.id === 'powerBuff');
        });
        if (healSkill) return healSkill;
      }
      // 그 외에는 데미지 스킬
      return validSkills[0];

    case 'balanced':
    default:
      // HP가 낮으면 생존 우선
      if (hpPercent < 0.3) {
        const healSkill = validSkills.find(slot => {
          const skill = skillData[slot - 1];
          return skill && skill.id === 'heal';
        });
        if (healSkill) return healSkill;
      }

      // 우선순위 기반 선택 (첫 번째로 조건을 만족하는 스킬)
      return validSkills[0];
  }
}

/**
 * 이동 방향 결정
 * @returns 목표 각도 (라디안)
 */
export function decideMovementDirection(
  aiConfig: AIConfig,
  monsterX: number,
  monsterY: number,
  playerX: number,
  playerY: number,
  monsterHP: number,
  monsterMaxHP: number
): number | null {
  const dx = playerX - monsterX;
  const dy = playerY - monsterY;
  const distance = Math.sqrt(dx * dx + dy * dy);
  const angleToPlayer = Math.atan2(dy, dx);
  const hpPercent = monsterHP / monsterMaxHP;

  switch (aiConfig.type) {
    case 'aggressive':
      // 항상 플레이어를 추격
      if (distance > 50) {
        return angleToPlayer;
      }
      return null;

    case 'balanced':
      // HP가 낮으면 도망, 높으면 추격
      if (hpPercent < 0.3 && distance < 200) {
        // 도망
        return angleToPlayer + Math.PI;
      } else if (distance > 80) {
        // 추격
        return angleToPlayer;
      }
      return null;

    case 'defensive':
      // 어그로 범위 안에 있을 때만 추격
      if (distance < aiConfig.aggroRange && distance > 60) {
        return angleToPlayer;
      } else if (distance < 60) {
        // 너무 가까우면 약간 후퇴
        return angleToPlayer + Math.PI;
      }
      return null;

    case 'passive':
      // 플레이어가 너무 가까우면 도망
      if (distance < 150) {
        return angleToPlayer + Math.PI;
      }
      return null;

    default:
      return null;
  }
}

/**
 * 공격 여부 결정
 */
export function shouldAttack(aiConfig: AIConfig, distance: number, attackRange: number): boolean {
  if (aiConfig.type === 'passive') {
    return false; // 수동적 AI는 공격하지 않음
  }

  // 공격 범위 안에 있으면 공격
  return distance <= attackRange;
}

/**
 * 캐릭터 데이터 관리
 * 플레이어와 몬스터의 초기화 및 상태 관리 로직
 */

import { CharacterState, MonsterState } from './types';
import { defaultPlayerStats, defaultMonsterStats, MonsterStats } from '../gameData';
import { Skill } from '../skillSystem';
import {
  loadMonsterSkills,
  loadMonsterAI,
  loadMonsterAIPattern,
  loadMonsterBasicAttack,
} from '../combatSystem';
import { defaultAIPatternConfig } from '../monsterAI';
import { LevelConfig, calculateLevelStats } from '../levelSystem';

/**
 * 플레이어 캐릭터 초기화
 */
export function initializePlayer(
  canvasWidth: number,
  canvasHeight: number,
  testMode: boolean = false,
  basicAttack?: any
): CharacterState {
  return {
    position: testMode ? { x: 0, y: 0 } : { x: canvasWidth / 2, y: canvasHeight / 2 },
    stats: { ...defaultPlayerStats },
    isAttacking: false,
    isSkilling: false,
    attackCooldown: 0,
    meleeSwingStart: null,
    meleeSwingAngle: 0,
    meleeSwingHit: new Set(),
    skillSwingStart: null,
    skillSwingAngle: 0,
    skillSwingHit: new Set(),
    activeSkillType: null,
    activeSkillDamageMultiplier: 1.0,
    playerScale: 1,
    shakeOffset: { x: 0, y: 0 },
    skills: { slot1: null, slot2: null, slot3: null, slot4: null },
    basicAttack: basicAttack || null,
    skillPhase: 'idle' as const,
    skillPhaseStartTime: 0,
    currentSkillTiming: undefined,
  };
}

/**
 * 몬스터 초기화 파라미터
 */
interface MonsterInitParams {
  id: number;
  canvasWidth: number;
  canvasHeight: number;
  monsterData?: any; // 데이터셋의 행
  skillConfigs?: Record<string, Skill>;
  monsterLevelConfig?: LevelConfig; // 몬스터 레벨 설정
}

/**
 * 단일 몬스터 초기화
 */
export function createMonster(params: MonsterInitParams): MonsterState {
  const { id, canvasWidth, canvasHeight, monsterData, skillConfigs, monsterLevelConfig } = params;

  // 몬스터 데이터에서 정보 추출
  const monsterName = monsterData?.monster_name || `몬스터 ${id + 1}`;
  const monsterColor = monsterData?.monster_color || '#ff6b6b';

  // AI 패턴 로드
  const aiPatternConfig = monsterData ? loadMonsterAIPattern(monsterData) : defaultAIPatternConfig;
  const aiConfig = monsterData
    ? loadMonsterAI(monsterData)
    : {
        type: 'aggressive' as const,
        aggroRange: 300,
        skillPriority: 'damage' as const,
      };

  // 스킬 로드
  const monsterSkills = monsterData
    ? loadMonsterSkills(monsterData)
    : {
        slot1: null,
        slot2: null,
        slot3: null,
        slot4: null,
      };

  // 기본 공격 로드
  const monsterBasicAttackData = monsterData ? loadMonsterBasicAttack(monsterData) : null;

  const monsterBasicAttackSlot = monsterBasicAttackData
    ? {
        skill: skillConfigs?.[monsterBasicAttackData.id] || {
          id: monsterBasicAttackData.id,
          name: '기본 공격',
          category: 'basicAttack' as const,
          range: monsterBasicAttackData.range,
          area: monsterBasicAttackData.width,
          damageMultiplier: monsterBasicAttackData.damage,
          cooldown: monsterBasicAttackData.cooldown,
          spCost: monsterBasicAttackData.spCost,
          castTime: monsterBasicAttackData.castTime,
          visual: {
            effectShape: 'cone' as const,
            color: '#ef4444',
            secondaryColor: '#f87171',
            particleCount: 0,
            particleSize: 4,
            particleLifetime: 300,
          },
          animation: {
            castAnimation: 'none' as const,
            castScale: 1,
            cameraShake: 0,
          },
        },
        range: monsterBasicAttackData.range,
        width: monsterBasicAttackData.width,
        damage: monsterBasicAttackData.damage,
        cooldown: monsterBasicAttackData.cooldown,
        spCost: monsterBasicAttackData.spCost,
        castTime: monsterBasicAttackData.castTime,
      }
    : null;

  // 레벨 시스템을 사용하는 경우 레벨에 맞는 스탯 계산
  let monsterStats: MonsterStats;
  if (monsterLevelConfig) {
    const levelStats = calculateLevelStats(monsterLevelConfig);
    monsterStats = {
      hp: levelStats.hp,
      maxHp: levelStats.hp,
      attack: levelStats.attack,
      defense: levelStats.defense,
      speed: levelStats.speed,
      attackRange: defaultMonsterStats.attackRange,
      attackWidth: defaultMonsterStats.attackWidth,
      critRate: defaultMonsterStats.critRate || 0.05,
      critDamage: defaultMonsterStats.critDamage || 1.3,
      accuracy: defaultMonsterStats.accuracy || 0.85,
      evasion: defaultMonsterStats.evasion || 0.03,
    };
  } else {
    monsterStats = { ...defaultMonsterStats };
  }

  return {
    id,
    position: {
      x: Math.random() * (canvasWidth - 100) + 50,
      y: Math.random() * (canvasHeight - 100) + 50,
    },
    stats: monsterStats,
    isAttacking: false,
    attackCooldown: 0,
    isDead: false,
    aiState: 'CHASE',
    wanderTarget: null,
    wanderCooldown: 0,
    detectionRange: 9999, // 무제한 감지 범위
    respawnTimer: 0,
    velocity: { x: 0, y: 0 },
    knockbackTime: 0,
    name: monsterName,
    color: monsterColor,
    skills: monsterSkills,
    basicAttack: monsterBasicAttackSlot,
    aiConfig,
    aiPatternConfig,
    sp: monsterData?.monster_sp || 100,
    maxSP: monsterData?.monster_sp || 100,
    currentSkill: null,
    skillPhase: 'idle' as const,
    skillPhaseStartTime: 0,
    currentSkillTiming: undefined,
  };
}

/**
 * 몬스터 배치 초기화 파라미터
 */
interface MonsterBatchInitParams {
  count: number;
  canvasWidth: number;
  canvasHeight: number;
  monsterDataset?: any[];
  selectedMonsterRows?: Set<number>;
  skillConfigs?: Record<string, Skill>;
  selectMonsterByWeight?: () => any | null;
  currentDataRow?: any;
  startId?: number;
  monsterLevelConfig?: LevelConfig; // 몬스터 레벨 설정
}

/**
 * 여러 몬스터 일괄 초기화
 */
export function createMonsters(params: MonsterBatchInitParams): MonsterState[] {
  const {
    count,
    canvasWidth,
    canvasHeight,
    skillConfigs,
    selectMonsterByWeight,
    currentDataRow,
    startId = 0,
    monsterLevelConfig,
  } = params;

  const monsters: MonsterState[] = [];

  for (let i = 0; i < count; i++) {
    // 가중치 기반 선택 또는 현재 데이터 행 사용
    const selectedMonster = selectMonsterByWeight?.() || null;
    const monsterData = selectedMonster || currentDataRow;

    monsters.push(
      createMonster({
        id: startId + i,
        canvasWidth,
        canvasHeight,
        monsterData,
        skillConfigs,
        monsterLevelConfig,
      })
    );
  }

  return monsters;
}

/**
 * 플레이어 기본 공격 업데이트
 */
export function updatePlayerBasicAttack(player: CharacterState, basicAttack: any): void {
  if (!basicAttack) return;

  if (!player.basicAttack) {
    player.basicAttack = { ...basicAttack };
  } else {
    player.basicAttack.range = basicAttack.range;
    player.basicAttack.width = basicAttack.width;
    player.basicAttack.damage = basicAttack.damage;
    player.basicAttack.cooldown = basicAttack.cooldown;
    player.basicAttack.spCost = basicAttack.spCost;
    player.basicAttack.castTime = basicAttack.castTime;

    if (player.basicAttack.skill) {
      player.basicAttack.skill.range = basicAttack.range;
      player.basicAttack.skill.area = basicAttack.width;
      player.basicAttack.skill.damageMultiplier = basicAttack.damage;
      player.basicAttack.skill.cooldown = basicAttack.cooldown;
      player.basicAttack.skill.spCost = basicAttack.spCost;
      player.basicAttack.skill.castTime = basicAttack.castTime;
    }
  }
}

/**
 * 몬스터 기본 공격 업데이트 (배치)
 */
export function updateMonsterBasicAttacks(monsters: MonsterState[], basicAttack: any): void {
  if (!basicAttack) return;

  monsters.forEach(monster => {
    if (!monster.basicAttack) {
      monster.basicAttack = { ...basicAttack };
    } else {
      monster.basicAttack.range = basicAttack.range;
      monster.basicAttack.width = basicAttack.width;
      monster.basicAttack.damage = basicAttack.damage;
      monster.basicAttack.cooldown = basicAttack.cooldown;
      monster.basicAttack.spCost = basicAttack.spCost;
      monster.basicAttack.castTime = basicAttack.castTime;

      if (monster.basicAttack.skill) {
        monster.basicAttack.skill.range = basicAttack.range;
        monster.basicAttack.skill.area = basicAttack.width;
        monster.basicAttack.skill.damageMultiplier = basicAttack.damage;
        monster.basicAttack.skill.cooldown = basicAttack.cooldown;
        monster.basicAttack.skill.spCost = basicAttack.spCost;
        monster.basicAttack.skill.castTime = basicAttack.castTime;
      }
    }
  });
}

/**
 * 게임 루프 헬퍼 함수
 * 프레임 업데이트, 쿨다운 관리, 충돌 감지 등
 */

import { CharacterState, MonsterState, Projectile, SkillParticle, Position } from './types';
import { checkCollision } from '../gameData';
import { PROJECTILE_MAX_DISTANCE } from './constants';

/**
 * 공격 쿨다운 업데이트
 * @param character 캐릭터 또는 몬스터
 * @param deltaTime 경과 시간 (밀리초)
 */
export function updateAttackCooldown(
  character: CharacterState | MonsterState,
  deltaTime: number
): void {
  if (character.attackCooldown > 0) {
    character.attackCooldown = Math.max(0, character.attackCooldown - deltaTime);
  }
}

/**
 * 넉백 업데이트
 * @param monster 몬스터
 * @param deltaTime 경과 시간 (초)
 * @param decayRate 감쇠율
 */
export function updateKnockback(
  monster: MonsterState,
  deltaTime: number,
  decayRate: number = 0.9
): void {
  const knockbackDuration = 300; // 300ms
  const timeSinceKnockback = Date.now() - monster.knockbackTime;

  if (timeSinceKnockback < knockbackDuration) {
    // 넉백 적용
    monster.position.x += monster.velocity.x * deltaTime;
    monster.position.y += monster.velocity.y * deltaTime;

    // 속도 감쇠
    monster.velocity.x *= decayRate;
    monster.velocity.y *= decayRate;
  } else {
    // 넉백 종료
    monster.velocity = { x: 0, y: 0 };
  }
}

/**
 * 투사체 위치 업데이트
 * @param projectile 투사체
 * @param deltaTime 경과 시간 (초)
 */
export function updateProjectilePosition(projectile: Projectile, deltaTime: number): void {
  projectile.position.x += projectile.velocity.x * deltaTime;
  projectile.position.y += projectile.velocity.y * deltaTime;

  // 이동 거리 계산
  const dx = projectile.position.x - projectile.startPosition.x;
  const dy = projectile.position.y - projectile.startPosition.y;
  projectile.travelDistance = Math.sqrt(dx * dx + dy * dy);
}

/**
 * 유도 미사일 업데이트
 * @param projectile 투사체
 * @param target 타겟 (몬스터 또는 플레이어)
 * @param homingStrength 유도 강도 (0-1)
 * @param deltaTime 경과 시간 (초)
 */
export function updateHomingProjectile(
  projectile: Projectile,
  target: Position,
  homingStrength: number = 0.1,
  deltaTime: number
): void {
  if (!projectile.isHoming) return;

  const dx = target.x - projectile.position.x;
  const dy = target.y - projectile.position.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  if (distance > 0) {
    const currentSpeed = Math.sqrt(
      projectile.velocity.x * projectile.velocity.x + projectile.velocity.y * projectile.velocity.y
    );

    // 타겟 방향으로 속도 조정
    const targetVx = (dx / distance) * currentSpeed;
    const targetVy = (dy / distance) * currentSpeed;

    projectile.velocity.x += (targetVx - projectile.velocity.x) * homingStrength;
    projectile.velocity.y += (targetVy - projectile.velocity.y) * homingStrength;
  }
}

/**
 * 투사체가 유효한지 체크
 * @param projectile 투사체
 * @param canvasWidth 캔버스 너비
 * @param canvasHeight 캔버스 높이
 * @returns 유효 여부
 */
export function isProjectileValid(
  projectile: Projectile,
  canvasWidth: number,
  canvasHeight: number
): boolean {
  // 화면 밖으로 나갔는지 체크
  if (
    projectile.position.x < -50 ||
    projectile.position.x > canvasWidth + 50 ||
    projectile.position.y < -50 ||
    projectile.position.y > canvasHeight + 50
  ) {
    return false;
  }

  // 최대 이동 거리 체크
  if (projectile.travelDistance > PROJECTILE_MAX_DISTANCE) {
    return false;
  }

  return true;
}

/**
 * 파티클 업데이트
 * @param particle 파티클
 * @param deltaTime 경과 시간 (밀리초)
 */
export function updateParticle(particle: SkillParticle, deltaTime: number): void {
  particle.x += particle.vx;
  particle.y += particle.vy;
  particle.life -= deltaTime;
}

/**
 * 파티클이 유효한지 체크
 * @param particle 파티클
 * @returns 유효 여부
 */
export function isParticleValid(particle: SkillParticle): boolean {
  return particle.life > 0;
}

/**
 * 플레이어-투사체 충돌 감지
 * @param player 플레이어
 * @param projectile 투사체
 * @returns 충돌 여부
 */
export function checkPlayerProjectileCollision(
  player: CharacterState,
  projectile: Projectile
): boolean {
  return checkCollision(player.position, { size: player.stats.size }, projectile.position, {
    size: projectile.size,
  });
}

/**
 * 몬스터-투사체 충돌 감지
 * @param monster 몬스터
 * @param projectile 투사체
 * @returns 충돌 여부
 */
export function checkMonsterProjectileCollision(
  monster: MonsterState,
  projectile: Projectile
): boolean {
  if (monster.isDead) return false;

  return checkCollision(monster.position, { size: monster.stats.size }, projectile.position, {
    size: projectile.size,
  });
}

/**
 * 몬스터-파티클 충돌 감지 (새 이펙트 시스템용)
 * @param monster 몬스터
 * @param particle 파티클
 * @returns 충돌 여부
 */
export function checkMonsterParticleCollision(
  monster: MonsterState,
  particle: SkillParticle
): boolean {
  if (monster.isDead || particle.hasHit) return false;

  // 파티클이 투사체가 아니면 충돌하지 않음
  if (!particle.damage || !particle.owner) return false;

  return checkCollision(
    monster.position,
    { size: monster.stats.size },
    { x: particle.x, y: particle.y },
    { size: particle.size }
  );
}

/**
 * 플레이어-파티클 충돌 감지 (새 이펙트 시스템용)
 * @param player 플레이어
 * @param particle 파티클
 * @returns 충돌 여부
 */
export function checkPlayerParticleCollision(
  player: CharacterState,
  particle: SkillParticle
): boolean {
  if (particle.hasHit) return false;

  // 파티클이 투사체가 아니면 충돌하지 않음
  if (!particle.damage || !particle.owner) return false;

  return checkCollision(
    player.position,
    { size: player.stats.size },
    { x: particle.x, y: particle.y },
    { size: particle.size }
  );
}

/**
 * 플레이어-몬스터 근접 공격 충돌 감지 (부채꼴)
 * @param playerPos 플레이어 위치
 * @param playerAngle 플레이어가 바라보는 각도 (라디안)
 * @param monsterPos 몬스터 위치
 * @param attackRange 공격 범위
 * @param attackArc 공격 각도 (라디안)
 * @returns 충돌 여부
 */
export function checkMeleeAttackHit(
  playerPos: Position,
  playerAngle: number,
  monsterPos: Position,
  attackRange: number,
  attackArc: number
): boolean {
  const dx = monsterPos.x - playerPos.x;
  const dy = monsterPos.y - playerPos.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  // 범위 체크
  if (distance > attackRange) return false;

  // 각도 체크
  const angleToMonster = Math.atan2(dy, dx);
  let angleDiff = angleToMonster - playerAngle;

  // 각도 정규화 (-π ~ π)
  while (angleDiff > Math.PI) angleDiff -= 2 * Math.PI;
  while (angleDiff < -Math.PI) angleDiff += 2 * Math.PI;

  return Math.abs(angleDiff) <= attackArc / 2;
}

/**
 * FPS 계산
 * @param lastFrameTime 마지막 프레임 시간
 * @param currentTime 현재 시간
 * @returns [새 FPS 값, deltaTime (초)]
 */
export function calculateFPS(lastFrameTime: number, currentTime: number): [number, number] {
  const deltaTime = (currentTime - lastFrameTime) / 1000; // 초 단위
  const fps = deltaTime > 0 ? Math.round(1 / deltaTime) : 60;

  return [fps, deltaTime];
}

/**
 * 안전한 숫자 값 체크 (NaN, Infinity 방지)
 * @param value 검사할 값
 * @param defaultValue 기본값
 * @returns 안전한 값
 */
export function safeNumber(value: number, defaultValue: number = 0): number {
  if (!isFinite(value) || isNaN(value)) {
    return defaultValue;
  }
  return value;
}

/**
 * 안전한 위치 값 체크
 * @param position 위치
 * @param defaultPosition 기본 위치
 * @returns 안전한 위치
 */
export function safePosition(
  position: Position,
  defaultPosition: Position = { x: 0, y: 0 }
): Position {
  return {
    x: safeNumber(position.x, defaultPosition.x),
    y: safeNumber(position.y, defaultPosition.y),
  };
}

/**
 * 새로운 파티클 시스템 (5가지 이펙트 타입)
 * - projectile: 투사체 발사
 * - trail: 궤적 이펙트
 * - lightning: 번개 연결
 * - ring: 링/동심원
 * - glow: 글로우 + 상승 파티클
 */

import { EffectPreset } from '../skillSystem';
import { LightningSegment, MonsterState, Position, SkillParticle, TrailEffect } from './types';

let particleIdCounter = 0;

/**
 * 파티클 생성 옵션
 */
export interface CreateEffectOptions {
  preset: EffectPreset;
  position: Position;
  targetPosition?: Position;
  targetId?: number;
  owner?: 'player' | 'monster';
  monsterId?: number;
  damage?: number;
  skillName?: string; // 스킬 이름 (데미지 텍스트 표시용)
  skillArea?: number; // 스킬 범위/각도 (궤적 이펙트용, 도 단위)
  skillRange?: number; // 스킬 사거리 (궤적 이펙트 반지름용)
}

/**
 * ===== 투사체 이펙트 생성 =====
 */
export function createProjectileEffect(options: CreateEffectOptions): SkillParticle[] {
  const { preset, position, targetPosition, owner, monsterId, damage, skillName } = options;
  const particles: SkillParticle[] = [];

  if (!preset.projectilePattern || !preset.projectileCount) return particles;

  const count = preset.projectileCount;
  const speed = preset.projectileSpeed || 400;
  const size = preset.projectileSize || 8;
  const lifetime = preset.projectileLifetime || 1000;

  // 발사 각도 계산
  let baseAngle = 0;
  if (targetPosition) {
    const dx = targetPosition.x - position.x;
    const dy = targetPosition.y - position.y;
    baseAngle = Math.atan2(dy, dx);
  }

  for (let i = 0; i < count; i++) {
    let angle = baseAngle;

    // 패턴별 각도 조정
    switch (preset.projectilePattern) {
      case 'directional':
        // 방향성 발사 (약간의 스프레드)
        if (count > 1 && preset.spreadAngle) {
          const offset = (i - (count - 1) / 2) * (preset.spreadAngle / (count - 1));
          angle += offset;
        }
        break;

      case 'radial':
        // 방사형 발사 (360도 균등 분포)
        angle = (i / count) * Math.PI * 2;
        break;

      case 'cone': {
        // 부채꼴 발사
        const spreadAngle = preset.spreadAngle || Math.PI / 4;
        if (count > 1) {
          const offset = (i - (count - 1) / 2) * (spreadAngle / (count - 1));
          angle += offset;
        }
        break;
      }
    }

    // 속도 벡터 계산
    const vx = Math.cos(angle) * speed;
    const vy = Math.sin(angle) * speed;

    particles.push({
      id: particleIdCounter++,
      x: position.x,
      y: position.y,
      vx,
      vy,
      life: lifetime,
      maxLife: lifetime,
      size,
      color: preset.color,
      secondaryColor: preset.secondaryColor,
      effectType: 'projectile',
      texture: preset.particleTexture,
      glowIntensity: preset.glowIntensity,

      // 투사체 데이터
      damage,
      owner,
      monsterId,
      hasHit: false,
      startPosition: { x: position.x, y: position.y },
      travelDistance: 0,
      isHoming: preset.isHoming,
      targetId: preset.isHoming ? options.targetId : undefined,
      skillName,

      // 궤적 설정 (투사체는 항상 궤적을 남김)
      trailEnabled: true,
      trailHistory: [],
      trailLength: 20,
      trailWidth: size * 0.5,
    });
  }

  return particles;
}

/**
 * ===== 궤적 이펙트 생성 (TrailEffect 타입 사용) =====
 */
let trailIdCounter = 0;

export function createTrailEffectDirect(options: CreateEffectOptions): TrailEffect | null {
  const { preset, position, targetPosition, skillArea } = options;

  if (!preset.trailLength) return null;

  // 공격 방향 계산
  let angle = 0;
  if (targetPosition) {
    const dx = targetPosition.x - position.x;
    const dy = targetPosition.y - position.y;
    angle = Math.atan2(dy, dx);
  }

  // 스킬 범위(각도)에 따라 길이 조절
  // skillArea는 도 단위, 넓을수록 길어짐
  // 기본 범위(90도)를 기준으로 스케일 조정
  const areaMultiplier = skillArea ? skillArea / 90 : 1.0;
  const length = preset.trailLength * areaMultiplier;
  const width = preset.trailWidth || 5;
  const pointCount = preset.trailParticleCount || 20;
  const lifetime = 400; // 400ms 동안 표시

  // 궤적 타입별 점 생성
  const points: Position[] = [];

  if (preset.trailType === 'slash') {
    // 베기 - 호 모양
    // skillArea 값이 있으면 그 값을 호 각도로 사용, 없으면 기본 60도
    const arcAngle = skillArea ? (skillArea * Math.PI) / 180 : Math.PI / 3;
    const startAngle = angle - arcAngle / 2;

    for (let i = 0; i <= pointCount; i++) {
      const progress = i / pointCount;
      const currentAngle = startAngle + arcAngle * progress;
      const x = position.x + Math.cos(currentAngle) * length;
      const y = position.y + Math.sin(currentAngle) * length;
      points.push({ x, y });
    }
  } else if (preset.trailType === 'thrust') {
    // 찌르기 - 직선
    for (let i = 0; i <= pointCount; i++) {
      const progress = i / pointCount;
      const x = position.x + Math.cos(angle) * length * progress;
      const y = position.y + Math.sin(angle) * length * progress;
      points.push({ x, y });
    }
  } else if (preset.trailType === 'spin') {
    // 회전 - 원
    for (let i = 0; i <= pointCount; i++) {
      const currentAngle = (i / pointCount) * Math.PI * 2;
      const x = position.x + Math.cos(currentAngle) * length;
      const y = position.y + Math.sin(currentAngle) * length;
      points.push({ x, y });
    }
  }

  return {
    id: trailIdCounter++,
    points,
    color: preset.color,
    secondaryColor: preset.secondaryColor,
    width,
    life: lifetime,
    maxLife: lifetime,
    glowIntensity: preset.glowIntensity || 0.7,
  };
}

/**
 * ===== 궤적 이펙트 생성 (레거시 - 파티클 방식) =====
 */
export function createTrailEffect(options: CreateEffectOptions): SkillParticle[] {
  const { preset, position, targetPosition, skillArea, skillRange } = options;
  const particles: SkillParticle[] = [];

  // 🔍 디버깅: 전달받은 모든 값 확인
  console.log('🔴 [createTrailEffect] 호출됨', {
    presetId: preset.id,
    skillRange,
    skillArea,
    hasTargetPosition: !!targetPosition,
  });

  // CRITICAL: skillRange가 없으면 궤적 이펙트를 생성하지 않음
  // 궤적 이펙트는 반드시 스킬의 실제 범위를 따라야 하므로
  if (!skillRange) {
    console.warn('⚠️ [Trail Effect] skillRange가 없어서 궤적 이펙트를 생성하지 않습니다');
    return particles;
  }

  if (!preset.trailParticleCount) return particles;

  // 공격 방향 계산
  let angle = 0;
  if (targetPosition) {
    const dx = targetPosition.x - position.x;
    const dy = targetPosition.y - position.y;
    angle = Math.atan2(dy, dx);
  }

  // 스킬 사거리 사용 (위에서 이미 null 체크 완료)
  const radius = skillRange;
  const count = preset.trailParticleCount;
  const width = preset.trailWidth || 5;
  const fadeSpeed = preset.trailFadeSpeed || 1.0;
  const trailType = preset.trailType || 'thrust';

  // 디버깅: 실제 사용되는 값 출력
  if (preset.id === 'trail_slash' && Math.random() < 0.1) {
    console.log('🔴 [Trail Effect] 궤적 생성', {
      radius: `${radius}px`,
      skillArea: `${skillArea}°`,
      skillRange: `${skillRange}px`,
    });
  }

  // 이 궤적 그룹의 고유 ID (같은 휘두르기의 파티클들을 묶기 위해)
  const groupId = particleIdCounter;

  // 궤적 타입별 파티클 생성
  for (let i = 0; i < count; i++) {
    const progress = i / count;
    let x = position.x;
    let y = position.y;

    switch (trailType) {
      case 'slash': {
        // 호 형태 베기
        // CRITICAL: skillArea를 절대 우선 사용 (범위 UI와 일치하도록)
        const arcAngle =
          skillArea !== undefined
            ? (skillArea * Math.PI) / 180
            : preset.trailArcAngle || Math.PI / 2.5;

        const startAngle = angle - arcAngle / 2;
        const currentAngle = startAngle + arcAngle * progress;
        // 반지름은 skillRange 사용 (위에서 null 체크 완료)
        x = position.x + Math.cos(currentAngle) * radius;
        y = position.y + Math.sin(currentAngle) * radius;
        break;
      }
      case 'thrust': {
        // 직선 찌르기
        const distance = progress * radius;
        x = position.x + Math.cos(angle) * distance;
        y = position.y + Math.sin(angle) * distance;
        break;
      }
      case 'spin': {
        // 회전 궤적
        const currentAngle = progress * Math.PI * 2;
        x = position.x + Math.cos(currentAngle) * radius;
        y = position.y + Math.sin(currentAngle) * radius;
        break;
      }
    }

    // 약간의 랜덤 오프셋 (궤적에 두께감 추가)
    const offsetAngle = Math.atan2(y - position.y, x - position.x) + Math.PI / 2;
    const offsetDist = (Math.random() - 0.5) * width;
    const finalX = x + Math.cos(offsetAngle) * offsetDist;
    const finalY = y + Math.sin(offsetAngle) * offsetDist;

    particles.push({
      id: particleIdCounter++,
      x: finalX,
      y: finalY,
      vx: 0,
      vy: 0,
      life: 500 / fadeSpeed,
      maxLife: 500 / fadeSpeed,
      size: 5 + Math.random() * 3,
      color: preset.color,
      secondaryColor: preset.secondaryColor,
      effectType: 'trail',
      texture: preset.particleTexture,
      glowIntensity: preset.glowIntensity,
      skillType: `trail_${groupId}`, // 같은 그룹의 파티클들을 식별
    });
  }

  return particles;
}

/**
 * ===== 번개 이펙트 생성 =====
 */
export function createLightningEffect(options: CreateEffectOptions): SkillParticle[] {
  const { preset, position, targetPosition } = options;
  const particles: SkillParticle[] = [];

  if (!targetPosition || !preset.lightningSegments) return particles;

  const segments = preset.lightningSegments;
  const jitter = preset.lightningJitter || 10;
  const forkChance = preset.lightningForkChance || 0.2;

  // 번개 세그먼트 생성
  const lightningSegments: LightningSegment[] = [];

  // 메인 번개 경로
  let currentPos = { ...position };
  const dx = (targetPosition.x - position.x) / segments;
  const dy = (targetPosition.y - position.y) / segments;

  for (let i = 0; i < segments; i++) {
    const nextX = position.x + dx * (i + 1) + (Math.random() - 0.5) * jitter;
    const nextY = position.y + dy * (i + 1) + (Math.random() - 0.5) * jitter;

    lightningSegments.push({
      start: { ...currentPos },
      end: { x: nextX, y: nextY },
      brightness: 0.8 + Math.random() * 0.2,
    });

    // 번개 갈라짐
    if (Math.random() < forkChance && i < segments - 2) {
      const forkAngle = ((Math.random() - 0.5) * Math.PI) / 2;
      const forkDist = (segments - i) * Math.sqrt(dx * dx + dy * dy) * 0.5;
      const forkX = nextX + Math.cos(forkAngle) * forkDist;
      const forkY = nextY + Math.sin(forkAngle) * forkDist;

      lightningSegments.push({
        start: { x: nextX, y: nextY },
        end: { x: forkX, y: forkY },
        brightness: 0.5 + Math.random() * 0.3,
      });
    }

    currentPos = { x: nextX, y: nextY };
  }

  // 번개를 하나의 파티클로 표현 (세그먼트 정보 포함)
  particles.push({
    id: particleIdCounter++,
    x: position.x,
    y: position.y,
    vx: 0,
    vy: 0,
    life: 200,
    maxLife: 200,
    size: 2,
    color: preset.color,
    secondaryColor: preset.secondaryColor,
    effectType: 'lightning',
    texture: 'spark',
    glowIntensity: preset.glowIntensity,
    lightningSegments,
    lightningTarget: targetPosition,
  });

  return particles;
}

/**
 * ===== 링 이펙트 생성 =====
 */
export function createRingEffect(options: CreateEffectOptions): SkillParticle[] {
  const { preset, position } = options;
  const particles: SkillParticle[] = [];

  if (!preset.ringRadius || !preset.ringExpansionSpeed) return particles;

  const ringCount = preset.ringCount || 1;
  const interval = preset.ringInterval || 0;

  for (let i = 0; i < ringCount; i++) {
    const delay = i * interval;
    const startRadius = 10;
    const maxRadius = preset.ringRadius;
    const expansionSpeed = preset.ringExpansionSpeed;

    // 링을 구성하는 파티클 개수 (원주에 따라)
    const particleCount = Math.floor(maxRadius / 3);

    for (let j = 0; j < particleCount; j++) {
      const angle = (j / particleCount) * Math.PI * 2;

      particles.push({
        id: particleIdCounter++,
        x: position.x + Math.cos(angle) * startRadius,
        y: position.y + Math.sin(angle) * startRadius,
        vx: Math.cos(angle) * expansionSpeed,
        vy: Math.sin(angle) * expansionSpeed,
        life: ((maxRadius - startRadius) / expansionSpeed) * 1000 + delay,
        maxLife: ((maxRadius - startRadius) / expansionSpeed) * 1000 + delay,
        size: 4,
        color: preset.color,
        secondaryColor: preset.secondaryColor,
        effectType: 'ring',
        texture: preset.particleTexture,
        glowIntensity: preset.glowIntensity,
        ringRadius: startRadius,
        ringStartRadius: startRadius,
        ringExpansionSpeed: expansionSpeed,
      });
    }
  }

  return particles;
}

/**
 * ===== 글로우 이펙트 생성 =====
 */
export function createGlowEffect(options: CreateEffectOptions): SkillParticle[] {
  const { preset, position } = options;
  const particles: SkillParticle[] = [];

  if (!preset.glowRadius || !preset.glowParticleCount) return particles;

  const radius = preset.glowRadius;
  const count = preset.glowParticleCount;
  const riseSpeed = preset.glowRiseSpeed || 60;
  const fadeSpeed = preset.glowFadeSpeed || 0.8;

  // 중앙 글로우 파티클
  particles.push({
    id: particleIdCounter++,
    x: position.x,
    y: position.y,
    vx: 0,
    vy: 0,
    life: 1000 / fadeSpeed,
    maxLife: 1000 / fadeSpeed,
    size: radius,
    color: preset.color,
    secondaryColor: preset.secondaryColor,
    effectType: 'glow',
    texture: 'circle',
    glowIntensity: preset.glowIntensity,
  });

  // 상승하는 파티클들
  for (let i = 0; i < count; i++) {
    // 원형 영역 내 랜덤 위치
    const angle = Math.random() * Math.PI * 2;
    const dist = Math.random() * radius * 0.8;
    const x = position.x + Math.cos(angle) * dist;
    const y = position.y + Math.sin(angle) * dist;

    // 약간의 수평 이동 + 상승
    const vx = (Math.random() - 0.5) * 20;
    const vy = -riseSpeed;

    particles.push({
      id: particleIdCounter++,
      x,
      y,
      vx,
      vy,
      life: 1500 / fadeSpeed,
      maxLife: 1500 / fadeSpeed,
      size: 3 + Math.random() * 2,
      color: preset.color,
      secondaryColor: preset.secondaryColor,
      effectType: 'glow',
      texture: preset.particleTexture,
      glowIntensity: preset.glowIntensity * 0.7,
      riseSpeed,
    });
  }

  return particles;
}

/**
 * ===== 통합 이펙트 생성 함수 =====
 */
export function createEffect(options: CreateEffectOptions): SkillParticle[] {
  const { preset, skillRange, skillArea } = options;

  // 🔍 디버깅: 진입점 확인
  console.log('🟢 [createEffect] 호출됨', {
    presetId: preset.id,
    effectType: preset.effectType,
    skillRange,
    skillArea,
  });

  switch (preset.effectType) {
    case 'projectile':
      return createProjectileEffect(options);
    case 'trail':
      return createTrailEffect(options);
    case 'lightning':
      return createLightningEffect(options);
    case 'ring':
      return createRingEffect(options);
    case 'glow':
      return createGlowEffect(options);
    default:
      return [];
  }
}

/**
 * ===== 파티클 업데이트 =====
 */
export function updateNewParticle(
  particle: SkillParticle,
  deltaTime: number,
  monsters?: MonsterState[]
): SkillParticle {
  const updated = { ...particle };

  // 수명 감소
  updated.life = particle.life - deltaTime * 1000;

  switch (particle.effectType) {
    case 'projectile':
      // 유도 처리
      if (particle.isHoming && particle.targetId !== undefined && monsters) {
        const target = monsters.find(m => m.id === particle.targetId && !m.isDead);
        if (target) {
          const dx = target.position.x - particle.x;
          const dy = target.position.y - particle.y;
          const dist = Math.sqrt(dx * dx + dy * dy);

          if (dist > 0) {
            // 유도 강도
            const homingStrength = 300; // px/s²
            const ax = (dx / dist) * homingStrength * deltaTime;
            const ay = (dy / dist) * homingStrength * deltaTime;

            updated.vx = particle.vx + ax;
            updated.vy = particle.vy + ay;

            // 속도 제한
            const speed = Math.sqrt(updated.vx * updated.vx + updated.vy * updated.vy);
            const maxSpeed = 600;
            if (speed > maxSpeed) {
              updated.vx = (updated.vx / speed) * maxSpeed;
              updated.vy = (updated.vy / speed) * maxSpeed;
            }
          }
        }
      }

      // 위치 업데이트
      updated.x = particle.x + particle.vx * deltaTime;
      updated.y = particle.y + particle.vy * deltaTime;

      // 이동 거리 계산
      if (particle.startPosition) {
        const dx = updated.x - particle.startPosition.x;
        const dy = updated.y - particle.startPosition.y;
        updated.travelDistance = Math.sqrt(dx * dx + dy * dy);
      }

      // 궤적 업데이트
      if (particle.trailEnabled && particle.trailLength) {
        const now = Date.now();
        let newHistory = particle.trailHistory || [];
        newHistory = [...newHistory, { x: particle.x, y: particle.y, timestamp: now }];
        if (newHistory.length > particle.trailLength) {
          newHistory = newHistory.slice(-particle.trailLength);
        }
        updated.trailHistory = newHistory;
      }
      break;

    case 'trail':
      // 궤적은 정적 (위치 고정, 페이드만)
      break;

    case 'lightning':
      // 번개는 정적 (깜빡임 효과만)
      break;

    case 'ring':
      // 링 확장
      updated.x = particle.x + particle.vx * deltaTime;
      updated.y = particle.y + particle.vy * deltaTime;

      if (particle.ringRadius && particle.ringExpansionSpeed) {
        updated.ringRadius = particle.ringRadius + particle.ringExpansionSpeed * deltaTime;
      }
      break;

    case 'glow':
      // 글로우 파티클 상승
      if (particle.riseSpeed) {
        updated.x = particle.x + particle.vx * deltaTime;
        updated.y = particle.y + particle.vy * deltaTime;
      }
      break;
  }

  return updated;
}

/**
 * ===== 파티클 배열 업데이트 =====
 */
export function updateNewParticles(
  particles: SkillParticle[],
  deltaTime: number,
  monsters?: MonsterState[]
): SkillParticle[] {
  return particles
    .map(p => updateNewParticle(p, deltaTime, monsters))
    .filter(p => p.life > 0 && isFinite(p.x) && isFinite(p.y));
}

/**
 * ===== 파티클 렌더링 =====
 */
export function renderNewParticle(ctx: CanvasRenderingContext2D, particle: SkillParticle): void {
  const alpha = Math.max(0, Math.min(1, particle.life / particle.maxLife));

  switch (particle.effectType) {
    case 'projectile':
      // 궤적 렌더링
      if (particle.trailEnabled && particle.trailHistory && particle.trailHistory.length > 1) {
        renderTrail(ctx, particle, alpha);
      }

      // 파티클 본체
      renderParticleBody(ctx, particle, alpha);
      break;

    case 'trail':
      renderParticleBody(ctx, particle, alpha);
      break;

    case 'lightning':
      renderLightning(ctx, particle, alpha);
      break;

    case 'ring':
      renderRingParticle(ctx, particle, alpha);
      break;

    case 'glow':
      renderGlowParticle(ctx, particle, alpha);
      break;

    default:
      renderParticleBody(ctx, particle, alpha);
  }
}

/**
 * 궤적 렌더링
 */
function renderTrail(ctx: CanvasRenderingContext2D, particle: SkillParticle, alpha: number): void {
  if (!particle.trailHistory || particle.trailHistory.length < 2) return;

  const now = Date.now();
  const maxAge = 1000;

  ctx.save();
  ctx.strokeStyle = particle.color;
  ctx.lineWidth = particle.trailWidth || 2;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  for (let i = 1; i < particle.trailHistory.length; i++) {
    const prev = particle.trailHistory[i - 1];
    const curr = particle.trailHistory[i];
    const age = now - curr.timestamp;
    const pointAlpha = Math.max(0, 1 - age / maxAge);
    const trailAlpha = pointAlpha * alpha * 0.7;

    const hexAlpha = Math.floor(trailAlpha * 255)
      .toString(16)
      .padStart(2, '0');
    ctx.strokeStyle = particle.color + hexAlpha;

    ctx.beginPath();
    ctx.moveTo(prev.x, prev.y);
    ctx.lineTo(curr.x, curr.y);
    ctx.stroke();
  }

  ctx.restore();
}

/**
 * 파티클 본체 렌더링
 */
function renderParticleBody(
  ctx: CanvasRenderingContext2D,
  particle: SkillParticle,
  alpha: number
): void {
  const glowRadius = particle.size * 2 * (particle.glowIntensity || 0.5);

  // 글로우 효과
  if (particle.glowIntensity && particle.glowIntensity > 0) {
    const gradient = ctx.createRadialGradient(
      particle.x,
      particle.y,
      0,
      particle.x,
      particle.y,
      glowRadius
    );
    const glowAlpha = Math.floor(alpha * particle.glowIntensity * 255)
      .toString(16)
      .padStart(2, '0');
    gradient.addColorStop(0, particle.color + glowAlpha);
    gradient.addColorStop(1, `${particle.color}00`);

    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(particle.x, particle.y, glowRadius, 0, Math.PI * 2);
    ctx.fill();
  }

  // 텍스쳐별 렌더링
  const hexAlpha = Math.floor(alpha * 255)
    .toString(16)
    .padStart(2, '0');
  ctx.fillStyle = particle.color + hexAlpha;

  switch (particle.texture) {
    case 'circle':
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
      ctx.fill();
      break;

    case 'star':
      renderStar(ctx, particle.x, particle.y, particle.size, 5);
      break;

    case 'square':
      ctx.fillRect(
        particle.x - particle.size,
        particle.y - particle.size,
        particle.size * 2,
        particle.size * 2
      );
      break;

    case 'diamond':
      renderDiamond(ctx, particle.x, particle.y, particle.size);
      break;

    case 'spark':
      renderSpark(ctx, particle.x, particle.y, particle.size);
      break;

    default:
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
      ctx.fill();
  }
}

/**
 * 번개 렌더링
 */
function renderLightning(
  ctx: CanvasRenderingContext2D,
  particle: SkillParticle,
  alpha: number
): void {
  if (!particle.lightningSegments) return;

  ctx.save();
  ctx.strokeStyle = particle.color;
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';

  // 글로우 레이어
  ctx.shadowBlur = 10;
  ctx.shadowColor = particle.color;

  for (const segment of particle.lightningSegments) {
    const segmentAlpha = alpha * segment.brightness;
    const hexAlpha = Math.floor(segmentAlpha * 255)
      .toString(16)
      .padStart(2, '0');
    ctx.strokeStyle = particle.color + hexAlpha;

    ctx.beginPath();
    ctx.moveTo(segment.start.x, segment.start.y);
    ctx.lineTo(segment.end.x, segment.end.y);
    ctx.stroke();
  }

  ctx.restore();
}

/**
 * 링 파티클 렌더링
 */
function renderRingParticle(
  ctx: CanvasRenderingContext2D,
  particle: SkillParticle,
  alpha: number
): void {
  renderParticleBody(ctx, particle, alpha);
}

/**
 * 글로우 파티클 렌더링
 */
function renderGlowParticle(
  ctx: CanvasRenderingContext2D,
  particle: SkillParticle,
  alpha: number
): void {
  // 큰 글로우 파티클 (중앙)
  if (particle.size > 20) {
    const gradient = ctx.createRadialGradient(
      particle.x,
      particle.y,
      0,
      particle.x,
      particle.y,
      particle.size
    );
    const centerAlpha = Math.floor(alpha * 0.3 * 255)
      .toString(16)
      .padStart(2, '0');
    const edgeAlpha = Math.floor(alpha * 0.05 * 255)
      .toString(16)
      .padStart(2, '0');
    gradient.addColorStop(0, particle.color + centerAlpha);
    gradient.addColorStop(0.5, particle.secondaryColor + edgeAlpha);
    gradient.addColorStop(1, `${particle.color}00`);

    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
    ctx.fill();
  } else {
    // 상승 파티클
    renderParticleBody(ctx, particle, alpha);
  }
}

/**
 * 별 모양 렌더링
 */
function renderStar(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  size: number,
  points: number
): void {
  ctx.beginPath();
  for (let i = 0; i < points * 2; i++) {
    const angle = (i * Math.PI) / points;
    const radius = i % 2 === 0 ? size : size * 0.5;
    const px = x + Math.cos(angle - Math.PI / 2) * radius;
    const py = y + Math.sin(angle - Math.PI / 2) * radius;
    if (i === 0) {
      ctx.moveTo(px, py);
    } else {
      ctx.lineTo(px, py);
    }
  }
  ctx.closePath();
  ctx.fill();
}

/**
 * 다이아몬드 모양 렌더링
 */
function renderDiamond(ctx: CanvasRenderingContext2D, x: number, y: number, size: number): void {
  ctx.beginPath();
  ctx.moveTo(x, y - size);
  ctx.lineTo(x + size, y);
  ctx.lineTo(x, y + size);
  ctx.lineTo(x - size, y);
  ctx.closePath();
  ctx.fill();
}

/**
 * 스파크 모양 렌더링
 */
function renderSpark(ctx: CanvasRenderingContext2D, x: number, y: number, size: number): void {
  ctx.beginPath();
  ctx.moveTo(x - size, y);
  ctx.lineTo(x + size, y);
  ctx.moveTo(x, y - size);
  ctx.lineTo(x, y + size);
  ctx.stroke();
}

/**
 * 파티클 배열 렌더링
 */
export function renderNewParticles(
  ctx: CanvasRenderingContext2D,
  particles: SkillParticle[],
  zoom?: number,
  testMode?: boolean
): void {
  // trail 파티클 그룹화 (skillType으로)
  const trailGroups = new Map<string, SkillParticle[]>();
  const otherParticles: SkillParticle[] = [];

  particles.forEach(particle => {
    if (particle.effectType === 'trail' && particle.skillType) {
      // skillType이 trail_xxx 형태로 그룹 ID가 포함되어 있음
      const key = particle.skillType;
      if (!trailGroups.has(key)) {
        trailGroups.set(key, []);
      }
      trailGroups.get(key)!.push(particle);
    } else {
      otherParticles.push(particle);
    }
  });

  // trail 그룹을 선으로 연결하여 렌더링
  trailGroups.forEach(group => {
    if (group.length > 1) {
      renderTrailGroup(ctx, group);
    }
  });

  // 나머지 파티클 렌더링
  otherParticles.forEach(particle => {
    if (particle.effectType) {
      renderNewParticle(ctx, particle);
    }
  });
}

/**
 * trail 파티클 그룹을 연결된 선으로 렌더링
 */
function renderTrailGroup(ctx: CanvasRenderingContext2D, particles: SkillParticle[]): void {
  if (particles.length === 0) return;

  // 생명력이 가장 높은 파티클의 알파값 사용
  const maxLife = Math.max(...particles.map(p => p.life));
  const maxMaxLife = Math.max(...particles.map(p => p.maxLife));
  const alpha = Math.max(0, Math.min(1, maxLife / maxMaxLife));

  const firstParticle = particles[0];
  const lineWidth = particles[0].size || 4;

  // 글로우 효과
  if (firstParticle.glowIntensity && firstParticle.glowIntensity > 0) {
    ctx.save();
    ctx.strokeStyle = firstParticle.color;
    ctx.lineWidth = lineWidth * 3;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.globalAlpha = alpha * firstParticle.glowIntensity * 0.3;
    ctx.shadowBlur = 15;
    ctx.shadowColor = firstParticle.color;

    ctx.beginPath();
    particles.forEach((p, i) => {
      if (i === 0) {
        ctx.moveTo(p.x, p.y);
      } else {
        ctx.lineTo(p.x, p.y);
      }
    });
    ctx.stroke();
    ctx.restore();
  }

  // 메인 선
  ctx.save();
  const hexAlpha = Math.floor(alpha * 255)
    .toString(16)
    .padStart(2, '0');
  ctx.strokeStyle = firstParticle.color + hexAlpha;
  ctx.lineWidth = lineWidth;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // 그라데이션 효과 (시작부터 끝까지)
  ctx.beginPath();
  particles.forEach((p, i) => {
    if (i === 0) {
      ctx.moveTo(p.x, p.y);
    } else {
      ctx.lineTo(p.x, p.y);
    }
  });
  ctx.stroke();

  // 보조 색상으로 더 얇은 선 (중앙)
  if (firstParticle.secondaryColor) {
    ctx.strokeStyle = firstParticle.secondaryColor + hexAlpha;
    ctx.lineWidth = lineWidth * 0.5;

    ctx.beginPath();
    particles.forEach((p, i) => {
      if (i === 0) {
        ctx.moveTo(p.x, p.y);
      } else {
        ctx.lineTo(p.x, p.y);
      }
    });
    ctx.stroke();
  }

  ctx.restore();
}

/**
 * 파티클 시스템
 * 스킬 이펙트 파티클 생성, 업데이트, 렌더링
 */

import { EFFECT_PRESETS, Skill } from '../skillSystem';
import {
  createEffect,
  createGlowEffect,
  createLightningEffect,
  createProjectileEffect,
  createRingEffect,
  createTrailEffect,
  renderNewParticle,
  renderNewParticles,
  updateNewParticle,
  updateNewParticles,
  type CreateEffectOptions,
} from './particles-new';
import { Position, SkillParticle } from './types';

// 새로운 5가지 이펙트 시스템 re-export
export {
  createEffect,
  createGlowEffect,
  createLightningEffect,
  createProjectileEffect,
  createRingEffect,
  createTrailEffect,
  renderNewParticle,
  renderNewParticles,
  updateNewParticle,
  updateNewParticles,
  type CreateEffectOptions,
};

/**
 * 파티클 타입별 업데이트 전략
 */
export type ParticleUpdateStrategy = 'projectile' | 'aoe_burst' | 'static';

export interface ParticleCreateOptions {
  position: Position;
  targetPosition?: Position;
  skill: Skill;
  count?: number;
  strategy: ParticleUpdateStrategy;
  // 투사체 정보 (파티클이 투사체 역할을 할 때)
  damage?: number;
  owner?: 'player' | 'monster';
  monsterId?: number;
}

/**
 * 원거리 공격 파티클 생성 (발사 방향으로 집중)
 */
export function createProjectileParticles(
  options: ParticleCreateOptions,
  particleIdCounter: { current: number }
): SkillParticle[] {
  const { position, targetPosition, skill, count } = options;
  const particles: SkillParticle[] = [];

  if (!targetPosition) return particles;

  const dx = targetPosition.x - position.x;
  const dy = targetPosition.y - position.y;
  const attackAngle = Math.atan2(dy, dx);

  // 투사체 속도 (픽셀/초)
  const baseSpeed = skill.projectile?.speed || 300;

  for (let i = 0; i < (count || skill.visual.particleCount); i++) {
    const spreadAngle = 0.3; // 좁은 스프레드
    const angle = attackAngle + (Math.random() - 0.5) * spreadAngle;
    const speed = baseSpeed * (0.8 + Math.random() * 0.4);
    const color = Math.random() > 0.5 ? skill.visual.color : skill.visual.secondaryColor;

    particles.push({
      id: particleIdCounter.current++,
      x: position.x,
      y: position.y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      life: skill.visual.particleLifetime,
      maxLife: skill.visual.particleLifetime,
      size: skill.visual.particleSize,
      color,
      skillType: skill.id,
      strategy: 'projectile',
    });
  }

  return particles;
}

/**
 * AOE 폭발 파티클 생성 (중심에서 사방으로 퍼짐)
 */
export function createAoeBurstParticles(
  options: ParticleCreateOptions,
  particleIdCounter: { current: number }
): SkillParticle[] {
  const { position, skill, count } = options;
  const particles: SkillParticle[] = [];

  for (let i = 0; i < (count || skill.visual.particleCount * 2); i++) {
    const angle = Math.random() * Math.PI * 2;
    const speed = 50 + Math.random() * 150; // 픽셀/초
    const color = Math.random() > 0.5 ? skill.visual.color : skill.visual.secondaryColor;

    particles.push({
      id: particleIdCounter.current++,
      x: position.x,
      y: position.y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      life: skill.visual.particleLifetime * 1.5,
      maxLife: skill.visual.particleLifetime * 1.5,
      size: skill.visual.particleSize * 1.2,
      color,
      skillType: skill.id,
      strategy: 'aoe_burst',
    });
  }

  return particles;
}

/**
 * 스킬 effectShape에 따른 파티클 생성 (스킬 전용)
 * 이펙트 자체가 투사체 역할을 함
 */
export function createSkillEffectParticles(
  options: ParticleCreateOptions,
  particleIdCounter: { current: number }
): SkillParticle[] {
  const { position, targetPosition, skill, count, damage, owner, monsterId } = options;
  const particles: SkillParticle[] = [];

  if (!targetPosition) return particles;

  const dx = targetPosition.x - position.x;
  const dy = targetPosition.y - position.y;
  const baseAngle = Math.atan2(dy, dx);
  const effectShape = skill.visual?.effectShape || 'circle';
  const particleCount = count || skill.visual.particleCount;

  // 투사체 속도 (원거리 스킬용)
  const isProjectile = skill.projectile?.type !== 'none';
  const projectileSpeed = isProjectile ? skill.projectile?.speed || 400 : 0;

  for (let i = 0; i < particleCount; i++) {
    let angle = 0;
    let distance = 0;
    let speed = 0;

    switch (effectShape) {
      case 'circle':
        if (isProjectile) {
          // 투사체 모드: 타겟 방향으로 원형 집단 이동
          angle = baseAngle + (Math.random() - 0.5) * 0.4;
          distance = Math.random() * 15;
          speed = projectileSpeed * (0.9 + Math.random() * 0.2);
        } else {
          // 영역 모드: 중심에서 사방으로 확산
          angle = Math.random() * Math.PI * 2;
          distance = Math.random() * skill.range * 0.3;
          speed = 3 + Math.random() * 3;
        }
        break;

      case 'cone': {
        // 부채꼴 형태
        const coneSpread = (skill.area * Math.PI) / 180 / 2;
        angle = baseAngle + (Math.random() - 0.5) * coneSpread * 2;
        distance = Math.random() * skill.range * 0.3;
        speed = isProjectile
          ? projectileSpeed * (0.8 + Math.random() * 0.4)
          : 3 + Math.random() * 4;
        break;
      }

      case 'line':
        // 직선 형태 (좁은 스프레드)
        angle = baseAngle + (Math.random() - 0.5) * 0.15;
        distance = Math.random() * 20;
        speed = isProjectile
          ? projectileSpeed * (0.9 + Math.random() * 0.2)
          : 4 + Math.random() * 3;
        break;

      case 'ring':
        // 링 형태 (테두리)
        angle = (i / particleCount) * Math.PI * 2 + Math.random() * 0.3;
        distance = skill.range * 0.7 + Math.random() * skill.range * 0.2;
        speed = 2 + Math.random() * 2;
        break;

      case 'star': {
        // 별 모양 (5개 꼭지점)
        const starPoint = Math.floor(i / (particleCount / 5));
        const pointAngle = (starPoint * Math.PI * 2) / 5;
        angle = baseAngle + pointAngle + (Math.random() - 0.5) * 0.4;
        distance = Math.random() * skill.range * 0.5;
        speed = isProjectile
          ? projectileSpeed * (0.8 + Math.random() * 0.4)
          : 3 + Math.random() * 3;
        break;
      }

      case 'shield':
        // 방패 형태 (반원)
        angle = baseAngle + (Math.random() - 0.5) * Math.PI;
        distance = skill.range * 0.6 + Math.random() * 20;
        speed = 1 + Math.random();
        break;

      case 'dome':
        // 돔 형태 (위쪽 반구)
        angle = Math.random() * Math.PI * 2;
        distance = Math.random() * skill.range * 0.8;
        speed = 1.5 + Math.random() * 1.5;
        break;

      case 'spiral': {
        // 나선 형태
        const spiralRot = (i / particleCount) * Math.PI * 4;
        angle = baseAngle + spiralRot;
        distance = (i / particleCount) * skill.range * 0.5;
        speed = isProjectile ? projectileSpeed * 0.8 : 2 + Math.random() * 2;
        break;
      }

      case 'cross': {
        // 십자 형태
        const crossArm = Math.floor((i / particleCount) * 4);
        angle = baseAngle + (crossArm * Math.PI) / 2 + (Math.random() - 0.5) * 0.2;
        distance = Math.random() * skill.range * 0.4;
        speed = isProjectile
          ? projectileSpeed * (0.8 + Math.random() * 0.4)
          : 3 + Math.random() * 3;
        break;
      }

      case 'wave': {
        // 파동 형태 (sine wave)
        const waveOffset = (i / particleCount - 0.5) * skill.range * 0.8;
        const perpAngle = baseAngle + Math.PI / 2;
        angle = baseAngle + (Math.random() - 0.5) * 0.1;
        distance = Math.abs(waveOffset) * 0.3;
        speed = isProjectile
          ? projectileSpeed * (0.9 + Math.random() * 0.2)
          : 3 + Math.random() * 3;

        // 파동 오프셋 적용
        const startX = position.x + Math.cos(perpAngle) * waveOffset;
        const startY = position.y + Math.sin(perpAngle) * waveOffset;

        const color = Math.random() > 0.5 ? skill.visual.color : skill.visual.secondaryColor;

        particles.push({
          id: particleIdCounter.current++,
          x: startX,
          y: startY,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          life: skill.visual.particleLifetime,
          maxLife: skill.visual.particleLifetime,
          size: skill.visual.particleSize,
          color,
          skillType: skill.id,
          strategy: isProjectile ? 'projectile' : 'aoe_burst',
          // 투사체 정보
          damage: isProjectile ? damage : undefined,
          owner: isProjectile ? owner : undefined,
          monsterId: isProjectile ? monsterId : undefined,
          hasHit: false,
          startPosition: isProjectile ? { x: startX, y: startY } : undefined,
          travelDistance: 0,
        });
        continue;
      }

      default:
        angle = Math.random() * Math.PI * 2;
        distance = Math.random() * skill.range;
        speed = 3 + Math.random() * 3;
    }

    const color = Math.random() > 0.5 ? skill.visual.color : skill.visual.secondaryColor;

    const startX = position.x + Math.cos(angle) * distance;
    const startY = position.y + Math.sin(angle) * distance;

    particles.push({
      id: particleIdCounter.current++,
      x: startX,
      y: startY,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      life: skill.visual.particleLifetime,
      maxLife: skill.visual.particleLifetime,
      size: skill.visual.particleSize,
      color,
      skillType: skill.id,
      strategy: isProjectile ? 'projectile' : 'aoe_burst',
      // 투사체 정보
      damage: isProjectile ? damage : undefined,
      owner: isProjectile ? owner : undefined,
      monsterId: isProjectile ? monsterId : undefined,
      hasHit: false,
      startPosition: isProjectile ? { x: startX, y: startY } : undefined,
      travelDistance: 0,
    });
  }

  return particles;
}

/**
 * 스킬 타입에 따라 적절한 파티클 생성
 */
export function createSkillParticles(
  options: ParticleCreateOptions,
  particleIdCounter: { current: number }
): SkillParticle[] {
  const { skill, strategy, position, targetPosition, damage, owner, monsterId } = options;

  // 새로운 이펙트 시스템 사용 (effectPresetId가 있으면)
  if (skill.visual.effectPresetId) {
    const preset = EFFECT_PRESETS[skill.visual.effectPresetId];
    if (preset) {
      // 🔍 디버깅: createEffect 호출 전 값 확인
      console.log('🔵 [createSkillParticles] createEffect 호출 직전', {
        skillId: skill.id,
        skillName: skill.name,
        presetId: skill.visual.effectPresetId,
        skillRange: skill.range,
        skillArea: skill.area,
      });

      return createEffect({
        preset,
        position,
        targetPosition,
        owner,
        monsterId,
        damage,
        skillName: skill.name,
        skillArea: skill.area, // 스킬 범위/각도 전달 (궤적 이펙트용)
        skillRange: skill.range, // 스킬 사거리 전달 (궤적 이펙트 반지름용)
      });
    }
  }

  // 기존 시스템 (하위 호환성)
  switch (strategy) {
    case 'projectile':
      return createProjectileParticles(options, particleIdCounter);

    case 'aoe_burst':
      return createAoeBurstParticles(options, particleIdCounter);

    case 'static':
      // 정적 이펙트 (위치 고정, 서서히 사라짐)
      return [];

    default:
      // 기본값: 스킬의 projectile 타입에 따라 자동 결정
      if (skill.projectile?.type !== 'none') {
        return createProjectileParticles(options, particleIdCounter);
      } else {
        // 스킬은 effectShape 기반 파티클 사용
        return createSkillEffectParticles(options, particleIdCounter);
      }
  }
}

/**
 * 파티클 업데이트 (전략 패턴)
 */
export function updateParticle(particle: SkillParticle, deltaTime: number): SkillParticle {
  const strategy = particle.strategy || 'projectile';
  const now = Date.now();

  switch (strategy) {
    case 'projectile':
    case 'aoe_burst': {
      // deltaTime 기반 업데이트 (픽셀/초)
      const newX = particle.x + particle.vx * deltaTime;
      const newY = particle.y + particle.vy * deltaTime;

      // 투사체 이동 거리 계산
      let newTravelDistance = particle.travelDistance || 0;
      if (particle.startPosition) {
        const dx = newX - particle.startPosition.x;
        const dy = newY - particle.startPosition.y;
        newTravelDistance = Math.sqrt(dx * dx + dy * dy);
      }

      // 궤적 히스토리 업데이트
      let newTrailHistory = particle.trailHistory || [];
      if (particle.trailEnabled && particle.trailLength && particle.trailLength > 0) {
        // 현재 위치를 히스토리에 추가
        newTrailHistory = [...newTrailHistory, { x: particle.x, y: particle.y, timestamp: now }];

        // 오래된 포인트 제거 (최대 길이 유지)
        if (newTrailHistory.length > particle.trailLength) {
          newTrailHistory = newTrailHistory.slice(-particle.trailLength);
        }
      }

      return {
        ...particle,
        x: newX,
        y: newY,
        life: particle.life - deltaTime * 1000,
        travelDistance: newTravelDistance,
        trailHistory: newTrailHistory,
      };
    }

    case 'static':
      // 위치 고정, 수명만 감소
      return {
        ...particle,
        life: particle.life - deltaTime * 1000,
      };

    default:
      return {
        ...particle,
        x: particle.x + particle.vx * deltaTime,
        y: particle.y + particle.vy * deltaTime,
        life: particle.life - deltaTime * 1000,
      };
  }
}

/**
 * 파티클 배열 업데이트 및 필터링
 */
export function updateParticles(particles: SkillParticle[], deltaTime: number): SkillParticle[] {
  return particles
    .filter((p): p is SkillParticle => {
      // undefined 파티클 제거 및 유효성 검사
      return !!(
        p &&
        typeof p.x === 'number' &&
        isFinite(p.x) &&
        isFinite(p.y) &&
        isFinite(p.vx) &&
        isFinite(p.vy) &&
        isFinite(p.size) &&
        isFinite(p.life) &&
        isFinite(p.maxLife) &&
        p.size > 0
      );
    })
    .map(p => updateParticle(p, deltaTime))
    .filter((p): p is SkillParticle => {
      // 수명이 다한 파티클 제거
      return isFinite(p.x) && isFinite(p.y) && isFinite(p.size) && p.size > 0 && p.life > 0;
    });
}

/**
 * 파티클 렌더링
 */
export function renderParticle(
  ctx: CanvasRenderingContext2D,
  particle: SkillParticle,
  skillConfigs?: Record<string, Skill>
): void {
  // 안전성 체크
  if (
    !isFinite(particle.x) ||
    !isFinite(particle.y) ||
    !isFinite(particle.size) ||
    !isFinite(particle.life) ||
    !isFinite(particle.maxLife) ||
    particle.size <= 0
  ) {
    return;
  }

  const alpha = particle.life / particle.maxLife;

  // 궤적 렌더링 (파티클 본체 전에)
  if (particle.trailEnabled && particle.trailHistory && particle.trailHistory.length > 1) {
    const trailWidth = particle.trailWidth || 2;
    const now = Date.now();

    ctx.save();

    // 선 스타일로 궤적 그리기
    ctx.strokeStyle = particle.color;
    ctx.lineWidth = trailWidth;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // 히스토리 포인트를 선으로 연결
    ctx.beginPath();
    for (let i = 0; i < particle.trailHistory.length; i++) {
      const point = particle.trailHistory[i];
      const age = now - point.timestamp;
      const maxAge = 1000; // 1초
      const pointAlpha = Math.max(0, 1 - age / maxAge);

      // 오래된 포인트일수록 투명하게
      const trailOpacity = pointAlpha * alpha * 0.7;
      const hexAlpha = Math.floor(trailOpacity * 255)
        .toString(16)
        .padStart(2, '0');

      if (i === 0) {
        ctx.moveTo(point.x, point.y);
      } else {
        // 그라디언트 효과를 위해 세그먼트별로 그리기
        const prevPoint = particle.trailHistory[i - 1];
        ctx.strokeStyle = particle.color + hexAlpha;
        ctx.beginPath();
        ctx.moveTo(prevPoint.x, prevPoint.y);
        ctx.lineTo(point.x, point.y);
        ctx.stroke();
      }
    }

    // 현재 위치까지 연결
    if (particle.trailHistory.length > 0) {
      const lastPoint = particle.trailHistory[particle.trailHistory.length - 1];
      const hexAlpha = Math.floor(alpha * 0.9 * 255)
        .toString(16)
        .padStart(2, '0');
      ctx.strokeStyle = particle.color + hexAlpha;
      ctx.beginPath();
      ctx.moveTo(lastPoint.x, lastPoint.y);
      ctx.lineTo(particle.x, particle.y);
      ctx.stroke();
    }

    ctx.restore();
  }

  // Glow effect
  if (particle.skillType && skillConfigs) {
    const skill = skillConfigs[particle.skillType];
    if (skill && skill.visual.glowIntensity > 0) {
      const glowRadius = particle.size * 2;

      if (!isFinite(glowRadius) || glowRadius <= 0) return;

      const gradient = ctx.createRadialGradient(
        particle.x,
        particle.y,
        0,
        particle.x,
        particle.y,
        glowRadius
      );
      gradient.addColorStop(
        0,
        particle.color +
          Math.floor(alpha * skill.visual.glowIntensity * 255)
            .toString(16)
            .padStart(2, '0')
      );
      gradient.addColorStop(1, `${particle.color}00`);
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, glowRadius, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // Main particle
  ctx.fillStyle =
    particle.color +
    Math.floor(alpha * 255)
      .toString(16)
      .padStart(2, '0');
  ctx.beginPath();
  ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
  ctx.fill();
}

/**
 * 파티클 배열 렌더링
 */
export function renderParticles(
  ctx: CanvasRenderingContext2D,
  particles: SkillParticle[],
  skillConfigs?: Record<string, Skill>
): void {
  particles.forEach(particle => {
    if (!particle || typeof particle.x !== 'number') return;
    renderParticle(ctx, particle, skillConfigs);
  });
}

/**
 * 시뮬레이터 렌더링 헬퍼
 * 캔버스 렌더링 관련 유틸리티 함수들
 */

import { CharacterState, MonsterState, Projectile, SkillParticle, Position } from './types';
import { CameraConfig, worldToScreen } from './camera';
import { PROJECTILE_FADE_START } from './constants';
import { safeNumber } from './gameLoop';

/**
 * 플레이어 렌더링
 */
export function drawPlayer(
  ctx: CanvasRenderingContext2D,
  player: CharacterState,
  cameraPos: Position,
  cameraConfig: CameraConfig,
  testMode: boolean
): void {
  let screenPos: Position;
  let scale = 1;

  if (testMode) {
    screenPos = worldToScreen(player.position, cameraPos, cameraConfig);
    scale = cameraConfig.zoom;
  } else {
    screenPos = player.position;
  }

  // 안전성 검사
  if (!isFinite(screenPos.x) || !isFinite(screenPos.y)) {
    return;
  }

  const size = safeNumber(player.stats.size, 20) * scale;
  const adjustedScale = safeNumber(player.playerScale, 1);

  ctx.save();
  ctx.translate(screenPos.x, screenPos.y);
  ctx.scale(adjustedScale, adjustedScale);

  // 플레이어 원 그리기
  ctx.beginPath();
  ctx.arc(0, 0, size, 0, Math.PI * 2);
  ctx.fillStyle = player.isAttacking ? '#fbbf24' : '#3b82f6';
  ctx.fill();
  ctx.strokeStyle = '#1e40af';
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.restore();
}

/**
 * 몬스터 렌더링
 */
export function drawMonster(
  ctx: CanvasRenderingContext2D,
  monster: MonsterState,
  cameraPos: Position,
  cameraConfig: CameraConfig,
  testMode: boolean
): void {
  if (monster.isDead) return;

  let screenPos: Position;
  let scale = 1;

  if (testMode) {
    screenPos = worldToScreen(monster.position, cameraPos, cameraConfig);
    scale = cameraConfig.zoom;
  } else {
    screenPos = monster.position;
  }

  // 안전성 검사
  if (!isFinite(screenPos.x) || !isFinite(screenPos.y)) {
    return;
  }

  const size = safeNumber(monster.stats.size, 24) * scale;

  ctx.save();

  // 몬스터 원 그리기
  ctx.beginPath();
  ctx.arc(screenPos.x, screenPos.y, size, 0, Math.PI * 2);
  ctx.fillStyle = monster.isAttacking ? '#dc2626' : monster.color || '#ef4444';
  ctx.fill();
  ctx.strokeStyle = '#991b1b';
  ctx.lineWidth = 2;
  ctx.stroke();

  // HP 바 그리기
  const hpBarWidth = size * 2;
  const hpBarHeight = 4 * scale;
  const hpPercent = monster.stats.hp / monster.stats.maxHp;

  ctx.fillStyle = '#1f2937';
  ctx.fillRect(
    screenPos.x - hpBarWidth / 2,
    screenPos.y - size - 8 * scale,
    hpBarWidth,
    hpBarHeight
  );

  ctx.fillStyle = hpPercent > 0.5 ? '#10b981' : hpPercent > 0.2 ? '#f59e0b' : '#ef4444';
  ctx.fillRect(
    screenPos.x - hpBarWidth / 2,
    screenPos.y - size - 8 * scale,
    hpBarWidth * hpPercent,
    hpBarHeight
  );

  ctx.restore();
}

/**
 * 투사체 렌더링 (파티클 이펙트)
 */
export function drawProjectile(
  ctx: CanvasRenderingContext2D,
  projectile: Projectile,
  cameraPos: Position,
  cameraConfig: CameraConfig,
  testMode: boolean
): void {
  let screenPos: Position;
  let scale = 1;

  if (testMode) {
    screenPos = worldToScreen(projectile.position, cameraPos, cameraConfig);
    scale = cameraConfig.zoom;
  } else {
    screenPos = projectile.position;
  }

  // 안전성 검사
  if (!isFinite(screenPos.x) || !isFinite(screenPos.y)) {
    return;
  }

  const size = safeNumber(projectile.size, 8) * scale;
  const baseColor = projectile.owner === 'player' ? '#60a5fa' : '#f87171';
  const glowColor = projectile.owner === 'player' ? '#3b82f6' : '#ef4444';

  // 페이드 아웃 효과
  let opacity = 1;
  if (projectile.travelDistance > PROJECTILE_FADE_START) {
    opacity = 1 - (projectile.travelDistance - PROJECTILE_FADE_START) / 100;
    opacity = Math.max(0, Math.min(1, opacity));
  }

  ctx.save();
  ctx.globalAlpha = opacity;

  // 파티클 개수와 크기
  const particleCount = 12;
  const coreSize = size * 0.8;
  const particleSize = size * 0.3;

  // 방향 계산 (속도 벡터)
  const vx = projectile.velocity.vx;
  const vy = projectile.velocity.vy;
  const angle = Math.atan2(vy, vx);

  // 중심 코어 그리기
  const coreGradient = ctx.createRadialGradient(
    screenPos.x,
    screenPos.y,
    0,
    screenPos.x,
    screenPos.y,
    coreSize
  );
  coreGradient.addColorStop(0, baseColor);
  coreGradient.addColorStop(0.5, `${baseColor}cc`);
  coreGradient.addColorStop(1, `${baseColor}00`);
  ctx.fillStyle = coreGradient;
  ctx.beginPath();
  ctx.arc(screenPos.x, screenPos.y, coreSize, 0, Math.PI * 2);
  ctx.fill();

  // 파티클들 그리기 (진행 방향으로 흩어짐)
  for (let i = 0; i < particleCount; i++) {
    const t = i / particleCount;
    const spread = Math.PI / 3; // 60도 확산
    const particleAngle = angle + (Math.random() - 0.5) * spread;
    const distance = size * (0.5 + Math.random() * 1.5);

    const px = screenPos.x + Math.cos(particleAngle) * distance;
    const py = screenPos.y + Math.sin(particleAngle) * distance;

    const particleAlpha = 0.3 + Math.random() * 0.4;

    const particleGradient = ctx.createRadialGradient(px, py, 0, px, py, particleSize);
    particleGradient.addColorStop(
      0,
      baseColor +
        Math.floor(particleAlpha * 255)
          .toString(16)
          .padStart(2, '0')
    );
    particleGradient.addColorStop(1, `${baseColor}00`);

    ctx.fillStyle = particleGradient;
    ctx.beginPath();
    ctx.arc(px, py, particleSize, 0, Math.PI * 2);
    ctx.fill();
  }

  // 외곽 발광 효과
  const outerGlow = ctx.createRadialGradient(
    screenPos.x,
    screenPos.y,
    coreSize,
    screenPos.x,
    screenPos.y,
    size * 2.5
  );
  outerGlow.addColorStop(0, `${glowColor}40`);
  outerGlow.addColorStop(0.5, `${glowColor}20`);
  outerGlow.addColorStop(1, 'transparent');
  ctx.fillStyle = outerGlow;
  ctx.beginPath();
  ctx.arc(screenPos.x, screenPos.y, size * 2.5, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

/**
 * 파티클 렌더링
 */
export function drawParticle(
  ctx: CanvasRenderingContext2D,
  particle: SkillParticle,
  cameraPos: Position,
  cameraConfig: CameraConfig,
  testMode: boolean
): void {
  let screenPos: Position;
  let scale = 1;

  if (testMode) {
    screenPos = worldToScreen({ x: particle.x, y: particle.y }, cameraPos, cameraConfig);
    scale = cameraConfig.zoom;
  } else {
    screenPos = { x: particle.x, y: particle.y };
  }

  // 안전성 검사
  if (!isFinite(screenPos.x) || !isFinite(screenPos.y)) {
    return;
  }

  const size = safeNumber(particle.size, 4) * scale;
  const lifePercent = particle.life / particle.maxLife;
  const opacity = Math.max(0, Math.min(1, lifePercent));

  ctx.save();
  ctx.globalAlpha = opacity;

  ctx.beginPath();
  ctx.arc(screenPos.x, screenPos.y, size, 0, Math.PI * 2);
  ctx.fillStyle = particle.color || '#ffffff';
  ctx.fill();

  // 발광 효과 (일부 스킬만)
  if (particle.skillType && particle.skillType.includes('slash')) {
    const gradient = ctx.createRadialGradient(
      screenPos.x,
      screenPos.y,
      0,
      screenPos.x,
      screenPos.y,
      size * 2
    );
    gradient.addColorStop(0, `${particle.color}80`);
    gradient.addColorStop(1, 'transparent');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(screenPos.x, screenPos.y, size * 2, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.restore();
}

/**
 * 부채꼴 공격 범위 렌더링 (스킬 페이즈별 색상)
 */
export function drawAttackRangeWithPhase(
  ctx: CanvasRenderingContext2D,
  centerPos: Position,
  targetPos: Position,
  range: number,
  arc: number,
  phase: 'idle' | 'windup' | 'execution' | 'recovery',
  cameraPos: Position,
  cameraConfig: CameraConfig,
  testMode: boolean
): void {
  let screenCenter: Position;
  let scale = 1;

  if (testMode) {
    screenCenter = worldToScreen(centerPos, cameraPos, cameraConfig);
    scale = cameraConfig.zoom;
  } else {
    screenCenter = centerPos;
  }

  // 안전성 검사
  if (!isFinite(screenCenter.x) || !isFinite(screenCenter.y)) {
    return;
  }

  const scaledRange = safeNumber(range, 100) * scale;

  // 페이즈별 색상
  let color: string;
  switch (phase) {
    case 'windup':
      color = '#fbbf2440'; // 노란색 (준비)
      break;
    case 'execution':
      color = '#ef444440'; // 빨간색 (공격)
      break;
    case 'recovery':
      color = '#3b82f640'; // 파란색 (후딜)
      break;
    default:
      color = '#94a3b820'; // 회색 (대기)
      break;
  }

  const dx = targetPos.x - centerPos.x;
  const dy = targetPos.y - centerPos.y;
  const angle = Math.atan2(dy, dx);

  ctx.save();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(screenCenter.x, screenCenter.y);
  ctx.arc(screenCenter.x, screenCenter.y, scaledRange, angle - arc / 2, angle + arc / 2);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

/**
 * 화면 클리어
 */
export function clearCanvas(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  backgroundColor: string = '#0f172a'
): void {
  ctx.fillStyle = backgroundColor;
  ctx.fillRect(0, 0, width, height);
}

/**
 * 그리드 렌더링 (테스트 모드용)
 */
export function drawGrid(
  ctx: CanvasRenderingContext2D,
  cameraPos: Position,
  cameraConfig: CameraConfig,
  gridSize: number = 100
): void {
  const { canvasWidth, canvasHeight, zoom } = cameraConfig;
  const scaledGridSize = gridSize * zoom;

  // 그리드 시작 오프셋 계산
  const offsetX = (cameraPos.x * zoom) % scaledGridSize;
  const offsetY = (cameraPos.y * zoom) % scaledGridSize;

  ctx.save();
  ctx.strokeStyle = '#1e293b';
  ctx.lineWidth = 1;

  // 세로선
  for (let x = -offsetX; x < canvasWidth; x += scaledGridSize) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, canvasHeight);
    ctx.stroke();
  }

  // 가로선
  for (let y = -offsetY; y < canvasHeight; y += scaledGridSize) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(canvasWidth, y);
    ctx.stroke();
  }

  ctx.restore();
}

/**
 * 몬스터 리스폰 시스템
 * 몬스터 리스폰 규칙과 로직을 관리합니다.
 */

import { MonsterState } from './types';
import { createMonster } from './characters';
import { Skill } from '../skillSystem';
import { DEFAULT_RESPAWN_DELAY } from './constants';
import { LevelConfig } from '../levelSystem';

/**
 * 리스폰 설정
 */
export interface RespawnConfig {
  enabled: boolean; // 리스폰 활성화 여부
  delay: number; // 리스폰 딜레이 (밀리초)
  maxCount: number; // 최대 몬스터 수
  canvasWidth: number;
  canvasHeight: number;
}

/**
 * 리스폰 컨텍스트
 */
export interface RespawnContext {
  monsterDataset?: any[];
  selectedMonsterRows?: Set<number>;
  skillConfigs?: Record<string, Skill>;
  selectMonsterByWeight?: () => any | null;
  currentDataRow?: any;
  nextMonsterId: number; // 다음 몬스터 ID
  monsterLevelConfig?: LevelConfig; // 몬스터 레벨 설정
}

/**
 * 죽은 몬스터의 리스폰 타이머 업데이트
 * @param monsters 몬스터 배열
 * @param deltaTime 프레임 경과 시간 (밀리초)
 * @param config 리스폰 설정
 * @param context 리스폰 컨텍스트
 * @returns 리스폰된 몬스터 수
 */
export function updateRespawnTimers(
  monsters: MonsterState[],
  deltaTime: number,
  config: RespawnConfig,
  context: RespawnContext
): number {
  if (!config.enabled) return 0;

  let respawnedCount = 0;
  const aliveCount = monsters.filter(m => !m.isDead).length;

  monsters.forEach(monster => {
    if (monster.isDead && monster.respawnTimer > 0) {
      monster.respawnTimer -= deltaTime;

      // 리스폰 조건: 타이머 완료 & 최대 수 미만
      if (monster.respawnTimer <= 0 && aliveCount + respawnedCount < config.maxCount) {
        respawnMonster(monster, config, context);
        respawnedCount++;
      }
    }
  });

  return respawnedCount;
}

/**
 * 몬스터 리스폰
 * @param monster 리스폰할 몬스터
 * @param config 리스폰 설정
 * @param context 리스폰 컨텍스트
 */
export function respawnMonster(
  monster: MonsterState,
  config: RespawnConfig,
  context: RespawnContext
): void {
  // 가중치 기반 선택 또는 현재 데이터 행 사용
  const selectedMonster = context.selectMonsterByWeight?.() || null;
  const monsterData = selectedMonster || context.currentDataRow;

  // 새로운 몬스터 데이터로 초기화
  const newMonster = createMonster({
    id: context.nextMonsterId++,
    canvasWidth: config.canvasWidth,
    canvasHeight: config.canvasHeight,
    monsterData,
    skillConfigs: context.skillConfigs,
    monsterLevelConfig: context.monsterLevelConfig,
  });

  // 기존 몬스터 상태에 새 데이터 복사
  Object.assign(monster, newMonster);

  // 리스폰 완료
  monster.isDead = false;
  monster.respawnTimer = 0;
}

/**
 * 몬스터 사망 처리
 * @param monster 사망한 몬스터
 * @param respawnDelay 리스폰 딜레이 (밀리초)
 */
export function killMonster(
  monster: MonsterState,
  respawnDelay: number = DEFAULT_RESPAWN_DELAY
): void {
  monster.isDead = true;
  monster.respawnTimer = respawnDelay;
  monster.stats.hp = 0;
}

/**
 * 살아있는 몬스터 수 계산
 * @param monsters 몬스터 배열
 * @returns 살아있는 몬스터 수
 */
export function countAliveMonsters(monsters: MonsterState[]): number {
  return monsters.filter(m => !m.isDead).length;
}

/**
 * 리스폰 대기 중인 몬스터 수 계산
 * @param monsters 몬스터 배열
 * @returns 리스폰 대기 중인 몬스터 수
 */
export function countRespawningMonsters(monsters: MonsterState[]): number {
  return monsters.filter(m => m.isDead && m.respawnTimer > 0).length;
}

/**
 * 모든 죽은 몬스터 즉시 리스폰
 * @param monsters 몬스터 배열
 * @param config 리스폰 설정
 * @param context 리스폰 컨텍스트
 * @returns 리스폰된 몬스터 수
 */
export function respawnAllDead(
  monsters: MonsterState[],
  config: RespawnConfig,
  context: RespawnContext
): number {
  let count = 0;
  const aliveCount = countAliveMonsters(monsters);

  monsters.forEach(monster => {
    if (monster.isDead && aliveCount + count < config.maxCount) {
      respawnMonster(monster, config, context);
      count++;
    }
  });

  return count;
}

